# --- T: the screen themes (2.3.10-b20, --comp-types) ------------------------------
# A "Theme" Settings row on page 3 (TOOLS > Settings), an enum like Keep CCs'
# (id 0x183: unregistered in stock and never an immediate in its code; a
# registry dump of the patched image and an immediate scan of stock's), saved
# in settings.tml as `theme`. T registers it, adds it to the global store
# (default Stock), and catches its post at the apply-all (boot) and the live
# edit: the value goes to the C (thm_post), NOT to the engine. The C's UI tick
# (character/theme.h) writes the 34-entry palette at 0x24000000, reloads the
# DMA2D CLUT the way boot does (0x080425e0) and marks the UI's widget tree
# dirty, so the renderer repaints every widget from the new palette.
THEME_ID = 0x183
THEME_RAM = 0x2406a644               # character/theme.h: THM_RAM (thm_ram_t: magic, req, Custom's colours)
THEME_BYTES = 104                    # thm_ram_t: 96, and 104 with THM_SAFE (2.3.11, the default)
THEME_VALUES = ("STOCK", "AMBER", "STAGE", "CONTRAST", "PHOSPHOR", "SYNTHWAVE", "CUSTOM")   # b26: no probes
THEME_ROW_VA = SETTINGS_P2_VA + 16   # Settings page 3, slot 0 (the row table: 8 u16 slots a page)
# b24-b25: the master bus's settings, kept across power-off (character/chr_save.h).
# Hidden registered integers (kind 1, as BPM's 0x66), no Settings row, four values
# seven bits apiece: the Character chain's Amount, Tone and Type rows (b24), then
# the compressor types' controls and auto makeup (b25). Ids unregistered in stock
# and never an immediate in it (the test proves both). Hook T offers 0x18d-0x19f
# to the C, which hands back the ids that are not these.
CHRSAVE_IDS = (0x18d, 0x18e, 0x18f, 0x191, 0x192, 0x193, 0x195, 0x196)
CHRSAVE_NAMES = (("Chr Amount:", "chramount"), ("Chr Tone:", "chrtone"), ("Chr Type:", "chrtype"),
                 ("Comp 1:", "cmpvals1"), ("Comp 2:", "cmpvals2"), ("Comp 3:", "cmpvals3"),
                 ("Comp 4:", "cmpvals4"), ("Comp 5:", "cmpvals5"))
CHRSAVE_SPAN = (0x18d, 0x19f)        # what T offers chr_post
CMP_SEED = ((36, 25, 24, 127, 64, 0), (64, 0, 64, 127, 127, 0), (64, 0, 0, 0, 127, 0))  # cmp_engine.h: cmp_defaults


def _pack7(vals):
    return sum(v << (7 * i) for i, v in enumerate(vals))


_CMP_FLAT = [v for row in CMP_SEED for v in row] + [0, 0]          # + auto makeup Off, + a spare
CHRSAVE_DEFAULTS = (0, _pack7([64] * 4), 0,                        # the Character store's seed: Tone 64
                    *(_pack7(_CMP_FLAT[4 * r:4 * r + 4]) for r in range(5)))
CHRSAVE_MAX = 0x0FFFFFFF
CHRSAVE_RAM = 0x2406c0b0             # chr_save.h: CHS_RAM (chs_ram_t: magic, the rows saved)
# b24: the patch's own colours, as the theme gives them (theme.h: THO_RAM): a magic
# then 13 ARGB1555 halfwords, read by the pop-up box and hook K's CPU bar.
THEME_OSD_RAM = 0x2406c0e0
THEME_OSD_MAGIC = 0x54484f31         # "THO1"
THEME_OSD_ROLES = ("box", "text", "bar", "bar 70%", "bar 90%", "peak", "bar background",
                   "strip internal", "strip CV", "strip MIDI", "strip off", "strip fallback", "strip parked")
THEME_OSD_STOCK = (0x8842, 0xffff, 0x83e0, 0xfe80, 0xfc00, 0xffff, 0x8842,
                   0xc210, 0x801f, 0x83e0, 0x8000, 0xffff, 0xfc00)   # 2.3.9's, exactly
DISPLAY_OBJ_LIT_VA = 0x0805bc78      # the renderer's present argument: the display object
THEME_EXTERNS = {
    "thm_x_cfgclut": 0x0804a8b0 | 1,  # HAL ConfigCLUT(h, {clut, mode, size} by value, layer)
    "thm_x_enclut": 0x0804a500 | 1,   # HAL EnableCLUT(h, layer): starts the load
    "thm_x_wait": 0x0804a536 | 1,     # waits for it (h, ms)
    "thm_x_fopen": 0x08056edc | 1,    # b23, Custom: FatFs f_open(fil, path, mode)
    "thm_x_fclose": 0x080576a6 | 1,   # f_close(fil)
    "thm_x_sdcheck": 0x0804440c | 1,  # b38: the card checked (opendir the root), remounted if that fails
    "thm_x_doc": 0x0809e50c | 1,      # TinyXML2 XMLDocument(doc, entities, whitespace)
    "thm_x_undoc": 0x0809d06c | 1,    # ~XMLDocument(doc)
    "thm_x_loadfile": 0x0808edc4 | 1, # the file thread's tml read and parse (path, buf, n, doc)
    "thm_x_child": 0x0809d608 | 1,    # XMLNode::FirstChildElement(node, name)
    "thm_x_attr": 0x0809dca8 | 1,     # XMLElement::Attribute(el, name, 0)
    "thm_x_savefile": 0x0808ed14 | 1, # the file thread's tml write (path, printer, buf, n)
    "thm_x_malloc": 0x08042e58 | 1,   # the heap (the tml read's own buffer)
    "thm_x_free": 0x08042ebc | 1,
}
THEME_GUARDS = (                     # (va, bytes, what): the facts T and the C rest on
    (0x080e3d98, "000000005a5656ff141414fffcfcfcff", "the palette's flash image (Stock)"),
    (0x080426a4, "00000024", "the CLUT load's palette address, 0x24000000"),
    (0x0804263a, "2123", "... its size, 0x21"),
    (0x08040e80, "c80d0024", "the UI task's UI-object pointer, 0x24000dc8"),
    (0x0805bb1c, "04f52076", "the renderer's widget root: UI object + 0x280"),
    (0x08070882, "94f83820", "the dirty test reads the root's +0x38 ..."),
    (0x0807088c, "94f83920", "... and +0x39"),
    (0x08060bf6, "94f83030", "the children draw skips only a hidden child (+0x30)"),
    (0x08069ed4, "00b589b0adf804108df806200293", "b24: the integer registrar (id, kind, label; min, max, xml on the stack)"),
    (0x0808d00a, "d4f8b422d4f8b012", "the file thread's buffer and its size: +0x2b4, +0x2b0"),
    (0x0808ee94, "70290224", "the tml read's FIL pointer, 0x24022970 ..."),
    (0x0808edbc, "70290224", "... and the tml write's"),
    (0x0808edda, "5822", "the FIL cleared: 0x58 bytes"),
    (0x0808ede4, "0122", "the tml read opens FA_READ"),
    (0x0808ed42, "0a22", "the tml write opens FA_WRITE | FA_CREATE_ALWAYS"),
    (0x0808ed1a, "d1f8f070", "the tml write's length: the printer's +0xf0 ..."),
    (0x0808ed34, "d1f8d4b0", "... and its text, +0xd4"),
    (0x0808c920, "809c0024", "b38: the SD card object, 0x24009c80, as the preset jobs pass it"),
    (0x0804440c, "10b50446037d33b9", "b38: the card check's entry (push; r4 = the card; its +0x14)"),
)
THEME_CALLS = (                      # (site, stock target): branch_target proves each
    (0x0804264c, 0x0804a8b0),        # boot's ConfigCLUT, layer 0
    (0x0804265c, 0x0804a500),        # its EnableCLUT
    (0x08042654, 0x0804a536),        # its wait
    (0x0805bb24, 0x08070866),        # the renderer's dirty test
    (0x0805bb5a, 0x080708a0),        # and its draw of the tree
    (0x0808e6e4, 0x0808d018),        # b23: the file thread's job 4, the settings load
    (0x0808e6d2, 0x0808d000),        # its job 5, the settings save
    (0x0808edea, 0x08056edc),        # the tml read's f_open
    (0x0808ee5c, 0x080576a6),        # its f_close
    (0x0808ee0a, 0x08042e58),        # its buffer from the heap
    (0x0808ee56, 0x08042ebc),        # and back
    (0x0805bdf0, 0x0809e50c),        # the settings load: XMLDocument() ...
    (0x0805bdfc, 0x0808edc4),        # ... the tml read ...
    (0x0805be14, 0x0809d608),        # ... FirstChildElement ...
    (0x0805beb4, 0x0809dca8),        # ... Attribute ...
    (0x0805be06, 0x0809d06c),        # ... ~XMLDocument
    (0x0805bd8c, 0x0808ed14),        # the settings save's tml write
    (0x0808c8a2, 0x0804440c),        # b38: a preset job's card check
    (0x0808d194, 0x0804440c),        # and the other's
)
THEME_SITES = (                      # (site, entry, what): T's head insertions
    (0x0806abbc, "treg", "the uiflip registration"),
    (0x08089efe, "tstore", "the global store's entries"),
    (0x0807c5be, "tpost", "the Settings apply-all post"),
    (0x0807d51c, "tedit", "the Settings live-edit post"),
    (0x0808e6e4, "tload", "the file thread's settings load (b23: theme.tml)"),
    (0x0808e6d2, "tsave", "its settings save (b23: the starter theme.tml)"),
)


def build_theme_hook(org, nexts, post_fn, job_fn, chr_fn):
    src = f"""
.syntax unified
.thumb
.section .text
.global _sT
.thumb_func
_sT:
treg:                               /* r0 = registry; as Q's qreg */
    push    {{r0, r1, r2, r3, r4, r12, lr}}
    sub     sp, #12
    movw    r1, #0x{THEME_ID:x}
    adr.w   r2, tlabel
    adr.w   r3, tvalues
    movs    r4, #{len(THEME_VALUES)}
    str     r4, [sp]
    adr.w   r4, txml
    str     r4, [sp, #4]
treg_call:
    .short  0, 0                    /* enum registrar */
{"".join(f'''    ldr     r0, [sp, #12]           /* b24: {CHRSAVE_NAMES[k][1]}, an integer like BPM */
    movw    r1, #0x{CHRSAVE_IDS[k]:x}
    movs    r2, #1
    adr.w   r3, tclabel{k}
    movs    r4, #0
    str     r4, [sp]
    ldr     r4, =0x{CHRSAVE_MAX:x}
    str     r4, [sp, #4]
    adr.w   r4, tcxml{k}
    str     r4, [sp, #8]
treg_c{k}:
    .short  0, 0                    /* integer registrar */
''' for k in range(len(CHRSAVE_IDS)))}    add     sp, #12
    pop     {{r0, r1, r2, r3, r4, r12, lr}}
treg_next:
    .short  0, 0

tstore:                             /* r0 = the global store */
    push    {{r0, r1, r2, r3, r12, lr}}
    movw    r1, #0x{THEME_ID:x}
    movs    r2, #0                  /* default Stock */
tstore_call:
    .short  0, 0                    /* AddParam */
{"".join(f'''    ldr     r0, [sp]                /* b24: {CHRSAVE_NAMES[k][1]} */
    movw    r1, #0x{CHRSAVE_IDS[k]:x}
    ldr     r2, =0x{CHRSAVE_DEFAULTS[k]:x}
tstore_c{k}:
    .short  0, 0                    /* AddParam */
''' for k in range(len(CHRSAVE_IDS)))}    pop     {{r0, r1, r2, r3, r12, lr}}
tstore_next:
    .short  0, 0

tpost:                              /* PostSetParam(r0 mgr, r1 key, r2 id, r3 value): boot's apply-all */
    movw    r12, #0x{THEME_ID:x}
    cmp     r2, r12
    beq     tmine
    subw    r12, r2, #0x{CHRSAVE_SPAN[0]:x}
    cmp     r12, #{CHRSAVE_SPAN[1] - CHRSAVE_SPAN[0]}
    bls     tchr
tpost_next:
    .short  0, 0
tedit:                              /* the same, from a live edit on the Settings screen */
    movw    r12, #0x{THEME_ID:x}
    cmp     r2, r12
    beq     tmine
tedit_next:
    .short  0, 0
tmine:                              /* ours: to the C, NOT to the engine */
    push    {{r0, r1, r2, r3, r12, lr}}
    mrs     r1, apsr
    vmrs    r2, fpscr
    push    {{r1, r2}}
    vpush   {{s0-s15}}
    mov     r0, r3
tpost_call:
    .short  0, 0                    /* bl thm_post(value) */
    vpop    {{s0-s15}}
    pop     {{r1, r2}}
    msr     apsr_nzcvq, r1
    vmsr    fpscr, r2
    pop     {{r0, r1, r2, r3, r12, pc}}
tchr:                               /* b24: the master bus's saved rows, to the C */
    push    {{r0, r1, r2, r3, r12, lr}}
    mrs     r1, apsr
    vmrs    r12, fpscr
    push    {{r1, r12}}
    vpush   {{s0-s15}}
    mov     r0, r2
    mov     r1, r3
tchr_call:
    .short  0, 0                    /* bl chr_post(id, value): 1 ours, 0 not */
    str     r0, [sp, #88]           /* into the saved r12 (scratch at a call) */
    vpop    {{s0-s15}}
    pop     {{r1, r2}}
    msr     apsr_nzcvq, r1
    vmsr    fpscr, r2
    pop     {{r0, r1, r2, r3, r12, lr}}
    cmp     r12, #0
    beq     tpost_next              /* not ours: on to the engine */
    bx      lr
{"".join(f'''
{e}:                              /* the file thread: r0 = its object, r1 the settings path */
    push    {{r0, r1, r2, r3, r12, lr}}
    mrs     r2, apsr
    vmrs    r3, fpscr
    push    {{r2, r3}}
    vpush   {{s0-s15}}
    movs    r1, #{k}                  /* 0: before the load, 1: before the save */
{e}_call:
    .short  0, 0                    /* bl thm_job(object, kind) */
    vpop    {{s0-s15}}
    pop     {{r2, r3}}
    msr     apsr_nzcvq, r2
    vmsr    fpscr, r3
    pop     {{r0, r1, r2, r3, r12, lr}}
{e}_next:
    .short  0, 0                    /* b.w the job */
''' for k, e in enumerate(("tload", "tsave")))}
    .balign 4
    .ltorg
{"".join(f'''    .balign 4
tclabel{k}:
    .asciz  "{CHRSAVE_NAMES[k][0]}"
    .balign 4
tcxml{k}:
    .asciz  "{CHRSAVE_NAMES[k][1]}"
''' for k in range(len(CHRSAVE_IDS)))}    .balign 4
tvalues:
    .word   {", ".join("0" for _ in THEME_VALUES)}       /* -> the value names */
    .balign 4
tlabel:
    .asciz  "Theme:"
    .balign 4
txml:
    .asciz  "theme"
    .balign 4
{"".join(f'''tv{i}:
    .asciz  "{v}"
    .balign 4
''' for i, v in enumerate(THEME_VALUES))}"""
    code, syms = assemble("hookT", src)
    code = bytearray(code)
    for sym, target, call in (
        ("treg_call", 0x08069e7c, True),
        ("treg_next", nexts["treg"], False),
        ("tstore_call", 0x0808951e, True),
        ("tstore_next", nexts["tstore"], False),
        ("tpost_call", post_fn, True),
        ("tpost_next", nexts["tpost"], False),
        ("tedit_next", nexts["tedit"], False),
        ("tchr_call", chr_fn, True),
        *((f"treg_c{k}", 0x08069ed4, True) for k in range(len(CHRSAVE_IDS))),
        *((f"tstore_c{k}", 0x0808951e, True) for k in range(len(CHRSAVE_IDS))),
        ("tload_call", job_fn, True),
        ("tload_next", nexts["tload"], False),
        ("tsave_call", job_fn, True),
        ("tsave_next", nexts["tsave"], False),
    ):
        off = syms[sym]
        code[off:off + 4] = enc_b_bl(org + off, target, call)
    struct.pack_into(f"<{len(THEME_VALUES)}I", code, syms["tvalues"],
                     *(org + syms[f"tv{i}"] for i in range(len(THEME_VALUES))))
    return bytes(code), syms


def apply_theme(d, n_org, n_syms):
    """Guard T's facts, append T, take each site at the head of its chain, and
    put the Theme row on Settings page 3."""
    _guard(d, CLK_REG_LIMIT_VA, CLK_REG_LIMIT, "parameter registry limit")
    _guard(d, CLK_STORE_CAP_VA, CLK_STORE_CAP, "global settings capacity")
    for va, raw, what in THEME_GUARDS:
        _guard(d, va, raw, what)
    for va, target in THEME_CALLS:
        if branch_target(d, va) != target:
            refuse(f"The call at {va:#x} is not what the themes expect.")
    if struct.unpack_from("<I", d, DISPLAY_OBJ_LIT_VA - BASE)[0] != DISPLAY_OBJ:
        refuse("The display object is not where the themes expect it.")
    if bytes(d[THEME_ROW_VA - BASE:THEME_ROW_VA - BASE + 16]) != bytes(16):
        refuse("Settings page 3 is not empty.")
    nexts = {entry: branch_target(d, site) for site, entry, _ in THEME_SITES}
    org = BASE + len(d)
    code, syms = build_theme_hook(org, nexts, n_org + n_syms["c_thm_post"], n_org + n_syms["c_thm_job"],
                                  n_org + n_syms["c_chr_post"])
    org2 = _append(d, bytearray(code))
    assert org2 == org
    for site, entry, _ in THEME_SITES:
        d[site - BASE:site - BASE + 4] = enc_b_bl(site, org + syms[entry], True)
    struct.pack_into("<H", d, THEME_ROW_VA - BASE, THEME_ID)
    vprint(f"T themes {len(code)} bytes at {org:#010x}, id {THEME_ID:#x}, ram {THEME_RAM:#x}")
    return org, syms


# --- Gate: Gate In and Round Robin (2.3.11 work, --gate-in; not hook G, the EQ's) --------------------------
# Two rows on each pad's own page, under Excl Group. "Gate In:" is Own (stock: the
# input in the pad's position), input 1-8, or None: an input fires every pad whose
# Gate In resolves to it, so several pads may share one input. "Round Robin:" Off /
# On / Random: of the pads one input fires, those On or Random take turns, one per
# rising edge; of the pads on one MIDI In channel, likewise one per note-on. In
# order, unless any of them is Random: then a random one, never the one that
# played last (b4). Pads Off fire every time, as stock. Each release or note-off
# goes to the pad its press fired. "Gate Action:" (b5 "Gate Does", split in b9) Play is all of the above; any
# other value makes the gate hold one of the pad's buttons instead of playing it:
# the rise posts that button's CC at 127 to the pad, the fall at 0, exactly the
# event the router's CC fan-out (0x080ab2a0) posts for a controller, so Clip Tempo
# and the pop-up take it as a held button. Such a pad never takes a turn.
# Recording (b15, owner; b6-b14's Gate Action Record, which also posted on the
# fall, is gone: a stored Record reads as Play). "Rec In:" on each pad's page and
# "Gate Rec:" (Rec Selected; b17: Settings page 2, after MIDI Rec) are Off / Record 1-8 / Replace 1-8, the
# number an input jack. At that jack's rise, before any pad plays, Record posts
# the UI event a MIDI Rec note posts (0x2b, 0x080aba98): stock starts a take into
# an empty pad, and stops a running take if it is that pad's. Replace posts clear
# (0x2c) first; the old WAV stays on the card. Rec In: pads on one jack take
# turns in screen order, one take each, the turn moving on only once the pad
# has content; a Record pad must be empty. Rec Selected: the selected pad, and
# it beats Rec In on the same jack. While a take runs, any jack with a job only
# stops it (0x2b for the selected pad, which stock selected for the take). The
# decisions are C (character/rec.h, rec_gate); the posts need MIDI Rec no more
# than the note's UI handler does: not at all.
# Mute and Solo (b7): CC 94 and CC 95 on a pad's MIDI In channel, 64 and up on,
# below off. A mute is what the Mixer's Mute Mode does (UI message 0x44,
# 0x0807e9c4): SetParam 0x47 (1 muted, traced in b19) to the pad, and the pad record's
# +0xd that the Mixer draws the red bar from. While any pad is soloed every other
# pad is muted; the last solo let go puts each pad back to its own mute, which is
# taken from what the module shows whenever nothing is soloed (so a Mixer mute is
# kept). A hook at the head of the MIDI CC post's chain (0x08093f14), with its own
# type gate, finds the channel's pads through the router's MIDI In records; the
# router is noted by gcap at every preset load. Across a preset load (b11,
# owner): Keep CCs ON mutes and solos the same pad positions again, through
# the same SetParam, after the load's own parameter posts (mfinal, at both
# FinalizeBankLoading sites, ahead of Clip Tempo's and Keep CCs' wrappers);
# OFF forgets them, as stock forgets the Mixer's mutes.
# The CV Action row (b12; b18-b20, owner): Off / Hold FX In 1-8 / Flip In 1-8.
# Hold FX In n: at a gate's rise, input n's voltage picks which Hold FX the gate
# holds (beating the Hold FX row; ghold -> cv_pick). Flip In n (b20): input n
# turns the pad's Live Flip mode like CC 117's knob, all the time, however the
# pad is played: the C does it from clip_read (clip_cv_flip), not the gate. One
# choice per semitone from 0 V (character/sidechain.h). Only the first pick
# after the row is set pops up (gcap_cv marks it), naming the choice.
# The delay's toggles (b13, owner): mcc notes CC 108-111 (any channel, as hook
# C takes them); after a load, Keep CCs ON posts each one sent since power-on
# again, as hook C does (on/off, or Width's 0-1000), since the preset's own
# delay settings come in with it. OFF forgets them. GATE-GROUPS-FEASIBILITY.md has the trace; HANDOVER-2.3.11.md the design.
# Both rows are registered, kept in both pad stores (so they save and load with
# the pad in preset.xml) and shown on tab 5 of all nine pad-mode pages (the row
# itself: 2.3.11-b1, hardware-confirmed). The router keeps a copy per pad (gcap),
# its three gate calls fan out to the pads (gon, goff), and its MIDI In loops'
# posts take turns (mon, moff).
GATE_IN_ID = 0x1a4                   # unregistered in stock; no immediate anywhere (2.3.11-b1 scan)
GATE_RR_ID = 0x1a5                   # likewise (2.3.11-b3 scan); the registry holds ids to 0x1d0
GATE_IN_VALUES = ("Own", "1", "2", "3", "4", "5", "6", "7", "8", "None")
GATE_RR_VALUES = ("Off", "On", "Random")
GATE_ACTION_ID = 0x1a6               # likewise (2.3.11-b5 scan: two movw hits are 0x1a65/0x1a69, offsets)
GATE_ACTION_VALUES = ("Play", "Hold FX")   # b9 (owner): was b5-b8's one "Gate Does" list; b15: Record left
GATE_HOLD_ID = 0x1a7                 # likewise (b5 scan: no immediate anywhere)
GATE_HOLDS = (                       # (Hold FX, the CC its gate holds): character/clip_tempo.h's buttons
    ("Roll", 118), ("Pitch Roll", 119), ("Freeze", 104), ("Pull Up", 105),
    ("Power Down", 107), ("Brake", 102), ("Scratch", 78),
)
GATE_HOLD_VALUES = ("Off",) + tuple(v for v, _ in GATE_HOLDS) + ("Random",)   # Random: a new one each gate, never the last;
                                     # b24 (owner): Off first, so a CV Hold FX In at 0 V holds nothing
GATE_CV_ID = 0x1a9                   # b12: free (no instruction takes it as a value; 0x1a8 is a common constant)
GATE_CV_VALUES = ("Off",) + tuple(f"Hold FX In {n}" for n in range(1, 9)) + tuple(f"Flip In {n}" for n in range(1, 9))   # b18: "In" (owner)
REC_IN_ID = 0x1ab                    # b15: unregistered in stock, and no instruction anywhere takes it
REC_SEL_ID = 0x1ad                   # likewise (0x1aa is a mov.w value; 0x1a1, 0x1a3 are a community fork's)
REC_VALUES = ("Off",) + tuple(f"Record {n}" for n in range(1, 9)) + tuple(f"Replace {n}" for n in range(1, 9))
REC_SEL_VALUES = tuple(v.upper() for v in REC_VALUES)   # b18 (owner): Gate Rec in capitals, as stock's Settings
GATE_ROWS = (0x1a4, 0x1a5, GATE_ACTION_ID, GATE_HOLD_ID, GATE_CV_ID, REC_IN_ID)   # ..., Hold FX, CV, Rec In
GATE_ROWS_ANY = (0x1a4, 0x1a5, REC_IN_ID)   # b25 (owner): every pad page; Gate Action, Hold FX, CV on Clip pages only
GATE3_RAM = 0x240693a8               # b12: the gap above the stack margin (test_firmware_memory: 0x100 clear)
GC_CV = 0x00                         # u8[9] per pad record: the CV row (0 Off, 1-8 Hold FX n, 9-16 Flip n)
GC_DTOUCH = 0x0c                     # u8[4]: CC 108-111 were sent since power-on (b13)
GC_DVAL = 0x10                       # u16[4]: their last 14-bit values
GATE3_BYTES = 0x18
GATE_REC_EVT = 0x2b                  # the UI event: record pad k = row * 4 + column (0x0807ff90's table)
GATE_CLEAR_EVT = 0x2c                # the UI event: clear pad k (0x0807c9c4: not while a take runs)
GATE_UI_LIST = 0x15288               # the UI list, at the router's context + this (0x080abb14)
GATE_UI_APPEND = 0x080a396c          # append(list, &event), as 0x080abab6
GATE_POST = 0x080a83a4               # post(ctx, &event, pad address), as the router's CC fan-out
GATE_IN_INPUTS = (0, 5, 1, 6, 2, 7, 3, 8)   # input 1-8 -> its router record (b16: the bench found b15's rows swapped)
GATE_IN_PADS = (0, 1, 2, 3, 5, 6, 7, 8)     # the 8 pads' router records; record 4 is a dummy
GATE_IN_REG_SITE = 0x0806abbc        # the registration chain J and T head (uiflip's)
GATE_IN_STORE_SITES = (              # each pad store's last AddParam(r4 store, 0xbd, 0): r4 survives the call
    (0x0808984c, "sample"),
    (0x080899ba, "samtempl, the empty pad"),
)
GATE_IN_TABS = (                     # tab 5 (Excl Group's) of the nine pad-mode row tables, 45 u16 slots
    0x080c6bde, 0x080c6dfa, 0x080c70ae, 0x080c72ca, 0x080c7882,
    0x080c7a9e, 0x080c7cba, 0x080c7fea, 0x080c8206,
)
GATE_CLIP_TABS = tuple(t + 3 * 0x5a for t in (0x080c6ad0, 0x080c6cec))   # b25: the two Clip pages' tab 5
assert set(GATE_CLIP_TABS) <= set(GATE_IN_TABS)                          # (CLIP_ROW_TABS' blocks, tab 2 + 3)
GATE_IN_CAP_SITE = 0x080ac0ec        # the param sub-switch's bhi.w for ids above 0xed
GATE_IN_CAP_STOCK = "bdf824304d3ba02b00f20681"   # ldrh r3,[sp,#0x24]; subs r3,#0x4d; cmp r3,#0xa0; bhi.w
GATE_IN_CAP_NEXT = 0x080ac2fc        # where that bhi.w goes: the forward to the pad
GATE_IN_CALLS = (                    # (site, stock target, entry): calls retargeted to the hook
    (0x080ac428, 0x080aaf78, "gon"),     # gate rise, default velocity: every real gate
    (0x080ac066, 0x080aaf78, "gon"),     # gate rise, event velocity: presses only, guarded anyway
    (0x080ac01c, 0x080ab118, "goff"),    # gate fall
    (0x080ab7a2, 0x080a83a4, "mon"),     # MIDI In loop, note-on: the post to one pad on the channel
    (0x080abb94, 0x080a83a4, "moff"),    # MIDI In loop, note-off
)
GATE_MIDI_NEXT = {"mon": 0x080ab7b2, "moff": 0x080abba4}   # each loop's next record: a skipped pad
GATE_IN_RAM = 0x2406f080             # patch RAM, uncleared at power-on: all of it under the magic
GI_GIN, GI_RR = 0x04, 0x0d           # u8[9] per pad record: Gate In, Round Robin
GI_CTRIN = 0x16                      # u8[9] per input record: whose turn
GI_FIRED = 0x1f                      # u8[9] per input record: the pads its rise fired, records 0-3, 5-8 as bits 0-7
GI_CTRCH = 0x28                      # u8[16] per MIDI channel: whose turn
GI_NEXT = 0x38                       # u8: the held-note slot to reuse when all are taken
GI_HELD = 0x39                       # 8 x {channel, note, pad record, in use}, bytes only: the notes a turn played
GI_SLOTS = 8
GI_SEED = 0x5c                       # u32: Random's xorshift state, stirred with the cycle counter
GATE_IN_BYTES = 0x60                 # exactly test_firmware_memory's 0x400 below the pool: full
GATE_IN_MAGIC = 0x4e495447           # "GTIN"
GATE2_RAM = 0x2406c3c0               # b5: Gate In's block is full; cleared under the same magic
GD_DOES = 0x00                       # u8[9] per pad record: Gate Action (0 Play, 1 Hold FX)
GD_BHELD = 0x09                      # u8[9] per input record: the button pads its rise pressed, as GI_FIRED
GD_HCC = 0x12                        # u8[9] per pad record: the CC its press sent, for its release
GD_OWNM = 0x1b                       # u8: the pads' own mutes, as gbit numbers them (b7)
GD_SOLO = 0x1c                       # u8: the pads soloed
GD_NOTCLIP = 0x1d                    # u8: the pads not Clip pads, as gbit numbers them: their gate plays (b25;
                                     # sidechain.h's clip_kind keeps it, CK_NOTCLIP)
GD_ROUTER = 0x20                     # u32: the router, noted by gcap
GD_HOLD = 0x24                       # u8[9] per pad record: Hold FX (b9; b24: 0 Off, 1-7, 8 Random)
GD_HLAST = 0x2d                      # u8[9] per pad record: the Hold FX Random picked last
GATE2_BYTES = 0x38
GATE_CC_MUTE, GATE_CC_SOLO = 94, 95  # patch_micro.py's CC map reserved them for this
GATE_P_ACTIVE = 0x47                 # the Mixer's mute: SetParam(MANAGER, pad, 0x47, 1 muted / 0 plays): its setter
                                     # 0x080a5d14 keeps it at +2; the process 0x080a5d64 copies the input through
                                     # at 0 and outputs a silent buffer (0x080a5e9e) at 1. b7-b15, b17-b18 had it
                                     # the other way round; a stale solo hid it on b16's bench
GATE_CC_MARK = 0x2a                  # b16: the low 7 bits of a CC gbtn sends; clip_tempo.h's CLIP_GATE_MARK
GATE_PADREC = SESSION_MGR + 0x7dc8   # 0x08078988: its 24-byte pad records, row * 120 + column * 24
GATE_PADREC_ACTIVE = 0x0d            # the record's "muted" byte, as 0x47: 0x0807ea0c writes it; a load leaves it 0
# SC In, the compressor's sidechain input (b8; b10: gates and MIDI only, owner):
# character/sidechain.h, and hook S, here. CC 49 picks Self, Gate 1-8 or MIDI.
# The Stock type's detector call (SIDECHAIN-FEASIBILITY.md section 3) goes to
# skey, which asks sc_key for the gate's or note's level; -1 means Self, and
# skey makes the stock call. VariMu and Thunder take the level from the C
# (cmp_types.h); Logical4 detects itself. gon/goff keep each input's level in
# the sidechain's gates byte; mcc counts the notes held on channel 16.
SC_RAM = 0x240693c0                  # character/sidechain.h: SC_RAM (2.3.12: moved, sdwake.c took 0x2406c020)
SC_MAGIC = 0x53434b32                # "SCK2" (b10's layout; b8's "SCK1" reads as Self)
SC_GATES, SC_MHELD, SC_MVEL = 6, 7, 8
SC_CVPICK, SC_CVSHOW = 9, 0x12       # b20: u8[9] per record, the CV row's last pick + 1; u16, records to pop up
SC_ROWSTALE = 0x14                   # b21: u8[8] per pad position, CC 112 moved its Clip Tempo (clip_row_tick)
SC_CCMOVED, SC_CCMETH = 0x1c, 0x1e  # b23: u8 a bit per pad position, CC 112/113 moved it; u16, 2 bits each, to what
SC_BYTES = 0x20
SC_MIDI_CHAN = 15                    # channel 16
SC_SITE = 0x080b9b68                 # bl 0x080a39d8: the block RMS (its other caller, 0x080a2520, is untouched)
SC_RMS = 0x080a39d8
SC_PROLOGUE = (0x080b9b04, 0x080b9b68)   # pins r5 = frames and r7 = msg at the site: stock, byte for byte
SC_PROLOGUE_SHA = "f8fa06345b6903788617180c6453c17549b5da3a8d83070cd3707e563beac2e9"
SC_EXTERNS = {                       # b10: gates and MIDI need no stock call (b8's audio keys did); b21:
    "clip_x_uipost": 0x0805b18c | 1,     # the Clip Tempo row's UI post(queue, &message), as 0x0807d4d4
}
REC_RAM = 0x240693e0                 # b15, character/rec.h: REC_RAM; between the sidechain's and the OSD's UI-side area
RC_IN = 0x00                         # u8[9] per pad record: Rec In (0 Off, 1-8 Record n, 9-16 Replace n)
RC_SEL = 0x09                        # u8: Rec Selected, as Rec In
RC_TURN = 0x0c                       # u8[8] per jack: the pad (screen order) its next search starts at
RC_PEND = 0x14                       # u8[8] per jack: the pad its last take went to, + 1; 0 none
RC_COUNT = 0x1c                      # u32: posts so far, each event's +4
REC_BYTES = 0x20                     # cleared by ginit with Gate In's, under its magic
REC_EXTERNS = {"rec_x_append": GATE_UI_APPEND | 1}   # the UI list's append, as the MIDI Rec note's 0x080abab6
REC_SEL_ROW_VA = SETTINGS_P2_VA + 2  # b17 (owner): Settings page 2, slot 1, after MIDI Rec (0xc3),
                                     # before Prog Change; the rows after it move one on, the last
                                     # to page 3 ahead of Theme
MIDI_REC_ID = 0xc3                   # "MIDI Rec:", page 2's first row (b16's bench: page 1 ends MIDI Keys)
REC_SEL_SITES = (                    # (site, entry, what): Rec Selected's head insertions, as T's
    (0x08089efe, "gsstore", "the global store's entries"),
    (0x0807c5be, "gspost", "the Settings apply-all post"),
    (0x0807d51c, "gsedit", "the Settings live-edit post"),
)
# The Clip Tempo row (b21, owner): Stock / Vinyl / Jungle / Key Lock, the same
# setting as CC 112, saved with the pad. On the Clip pages' tab with Loop Mode,
# Beat Count, Quant Size and Sync, after Sync. An edit, and a load posting the
# saved value, reach the Clip voice's own setter (ids above 0xd5, 0x080b6f04):
# grow hands id 0x1ae to the C (clip_row), on the audio task as CC 112, so the
# two never race. CC 112 marks the pad and the UI tick writes its store and
# posts UI message 0x66, so the row shows it and preset.xml saves it. Keep CCs
# ON: mfinal has the C write each pad's Clip Tempo into the new stores before
# Finalize posts them; OFF: the preset's own (LoadBank rebuilds every store
# from its defaults first, so a preset saved before b21 loads Stock).
CLIP_ROW_ID = 0x1ae                  # free in stock: no immediate, no literal; both voices ignore it
CLIP_ROW_VALUES = ("Stock", "Vinyl", "Jungle", "Key Lock")   # clip_tempo.h: CLIP_OFF ... CLIP_KEYLOCK
CLIP_ROW_TABS = (0x080c6ad0, 0x080c6cec)   # the two Clip pages' tab 2: Loop Mode, Beat Count, Quant Size, Sync
CLIP_ROW_AFTER = 0x76                # Sync
CLIP_ROW_SITE = 0x080b6f04           # the Clip voice's setter, ids above 0xd5 (CLIP_ROW_BHI's target)
CLIP_ROW_BHI = 0x080b6cfc            # bhi.w 0x080b6f04, after cmp r4, #0xd5
CLIP_ROW_STOCK = "40f23f139c42f6d1"  # movw r3, #0x13f; cmp r4, r3; bne: r4 id, r5 voice, r1 clock, r6 event
CLIP_ROW_DONE = 0x080b6efa           # the setter's epilogue
# The freeze guard (b21). SetParam only queues on the UI command ring, and waits
# while more than 0x20 are queued; the audio task is the ring's only reader, so
# from the audio task it can wait for itself forever (the watchdog then
# resets). Mute, Solo (mapply) and, in this build, hook C's delay toggles post
# from the audio task: gdpost puts the event straight into the router's list,
# as the ring's own reader would (0x08095984, through MIDI_POST_FN, as the CC
# itself was posted), so nothing waits and no UI post can be raced.
HOOKC_SETP = 90                      # hook C's csetp: bl SetParam (FROZEN["hookC"])
# The pad store was full (b21): stock's 58 entries and Gate In's six fill the 64
# its allocator gives it (0x0808949e, the only writer of a store's capacity),
# and AddParam drops a 65th without a word. Stock copies a whole store with a
# memcpy of the source's count (the clipboard, SessionMgr + 0x80b8 / 0x80e8,
# the file thread's), so every store that can hold a pad's entries must grow
# together: all three sites that ask for 64 ask for 72. The other stores ask
# for 10 or 2. 64 bytes more each, from the SDRAM bump allocator, at boot.
STORE_CAP_SITES = ((0x08089e08, 0x08089e0a), (0x08089f98, 0x08089f9c), (0x0808954e, 0x08089550))   # movs r1, #0x40; its bl
STORE_CAP = 0x48
ENGINE_PTR = 0xa204                  # MANAGER + this: the engine, SetParam's ring owner
GG_VERSION = "2.3.12-mod"            # the default output from 2.3.12-mod (test builds b1-b25 before it)


def build_gate_hook(org, reg_next, midi_next, sc_key, final_next, cv_pick, rec_gate, clip_row, row_keep, nexts,
                    clip_kind):
    values = "".join(f"gv{i}:\n    .asciz  \"{v}\"\n    .balign 4\n" for i, v in enumerate(GATE_IN_VALUES))
    values += "".join(f"rv{i}:\n    .asciz  \"{v}\"\n    .balign 4\n" for i, v in enumerate(GATE_RR_VALUES))
    values += "".join(f"dv{i}:\n    .asciz  \"{v}\"\n    .balign 4\n" for i, v in enumerate(GATE_ACTION_VALUES))
    values += "".join(f"hv{i}:\n    .asciz  \"{v}\"\n    .balign 4\n" for i, v in enumerate(GATE_HOLD_VALUES))
    words = ", ".join("0" for _ in GATE_IN_VALUES)
    rwords = ", ".join("0" for _ in GATE_RR_VALUES)
    dwords = ", ".join("0" for _ in GATE_ACTION_VALUES)
    hwords = ", ".join("0" for _ in GATE_HOLD_VALUES)
    cwords = ", ".join("0" for _ in GATE_CV_VALUES)
    values += "".join(f"cv{i}:\n    .asciz  \"{v}\"\n    .balign 4\n" for i, v in enumerate(GATE_CV_VALUES))
    values += "".join(f"qv{i}:\n    .asciz  \"{v}\"\n    .balign 4\n" for i, v in enumerate(REC_VALUES))
    qwords = ", ".join("0" for _ in REC_VALUES)
    values += "".join(f"sv{i}:\n    .asciz  \"{v}\"\n    .balign 4\n" for i, v in enumerate(REC_SEL_VALUES))
    swords = ", ".join("0" for _ in REC_SEL_VALUES)
    values += "".join(f"wv{i}:\n    .asciz  \"{v}\"\n    .balign 4\n" for i, v in enumerate(CLIP_ROW_VALUES))
    wwords = ", ".join("0" for _ in CLIP_ROW_VALUES)
    rclear = "".join(f"    str     r1, [r3, #{k}]\n" for k in range(0, REC_BYTES, 4))
    g3clear = "".join(f"    str     r1, [r3, #{k}]\n" for k in range(0, GATE3_BYTES, 4))
    hccs = ", ".join(str(c) for c in (0,) + tuple(c for _, c in GATE_HOLDS))   # b24: Off holds CC 0, none
    gclear = "".join(f"    str     r1, [r3, #{k}]\n" for k in range(0, GATE2_BYTES, 4))
    src = f"""
.syntax unified
.thumb
.section .text
.global _sGate
.thumb_func
_sGate:
greg:                               /* r0 = registry; as T's treg */
    push    {{r0, r1, r2, r3, r4, r12, lr}}
    sub     sp, #12
    str     r0, [sp, #8]
    movw    r1, #0x{GATE_IN_ID:x}
    adr.w   r2, glabel
    adr.w   r3, gvalues
    movs    r4, #{len(GATE_IN_VALUES)}
    str     r4, [sp]
    adr.w   r4, gxml
    str     r4, [sp, #4]
greg_call:
    .short  0, 0                    /* enum registrar */
    ldr     r0, [sp, #8]
    movw    r1, #0x{GATE_RR_ID:x}
    adr.w   r2, rlabel
    adr.w   r3, rvalues
    movs    r4, #{len(GATE_RR_VALUES)}
    str     r4, [sp]
    adr.w   r4, rxml
    str     r4, [sp, #4]
greg_call2:
    .short  0, 0                    /* enum registrar */
    ldr     r0, [sp, #8]
    movw    r1, #0x{GATE_ACTION_ID:x}
    adr.w   r2, dlabel
    adr.w   r3, dvalues
    movs    r4, #{len(GATE_ACTION_VALUES)}
    str     r4, [sp]
    adr.w   r4, dxml
    str     r4, [sp, #4]
greg_call3:
    .short  0, 0                    /* enum registrar */
    ldr     r0, [sp, #8]
    movw    r1, #0x{GATE_HOLD_ID:x}
    adr.w   r2, hlabel
    adr.w   r3, hvalues
    movs    r4, #{len(GATE_HOLD_VALUES)}
    str     r4, [sp]
    adr.w   r4, hxml
    str     r4, [sp, #4]
greg_call4:
    .short  0, 0                    /* enum registrar */
    ldr     r0, [sp, #8]
    movw    r1, #0x{GATE_CV_ID:x}
    adr.w   r2, clabel
    adr.w   r3, cvalues
    movs    r4, #{len(GATE_CV_VALUES)}
    str     r4, [sp]
    adr.w   r4, cxml
    str     r4, [sp, #4]
greg_call5:
    .short  0, 0                    /* enum registrar */
    ldr     r0, [sp, #8]
    movw    r1, #0x{REC_IN_ID:x}
    adr.w   r2, qlabel
    adr.w   r3, qvalues
    movs    r4, #{len(REC_VALUES)}
    str     r4, [sp]
    adr.w   r4, qxml
    str     r4, [sp, #4]
greg_call6:
    .short  0, 0                    /* enum registrar */
    ldr     r0, [sp, #8]
    movw    r1, #0x{REC_SEL_ID:x}
    adr.w   r2, slabel
    adr.w   r3, svalues             /* Rec In's, in capitals */
    movs    r4, #{len(REC_SEL_VALUES)}
    str     r4, [sp]
    adr.w   r4, sxml
    str     r4, [sp, #4]
greg_call7:
    .short  0, 0                    /* enum registrar */
    ldr     r0, [sp, #8]
    movw    r1, #0x{CLIP_ROW_ID:x}
    adr.w   r2, wlabel
    adr.w   r3, wvalues
    movs    r4, #{len(CLIP_ROW_VALUES)}
    str     r4, [sp]
    adr.w   r4, wxml
    str     r4, [sp, #4]
greg_call8:
    .short  0, 0                    /* enum registrar */
    add     sp, #12
    pop     {{r0, r1, r2, r3, r4, r12, lr}}
greg_next:
    .short  0, 0

gstore:                             /* the store's own last AddParam, then Gate In = Own, Round Robin = Off, */
                                    /* Gate Action = Play, Hold FX = Roll (1 since b24's Off), CV = Off, Rec In = Off, */
                                    /* Clip Tempo = Stock */
    push    {{r0, r1, r2, r3, r12, lr}}
gstore_orig:
    .short  0, 0                    /* AddParam(r0, r1, r2), as the site called it */
    str     r0, [sp]                /* its result, back to the caller */
    mov     r0, r4                  /* the store */
    movw    r1, #0x{GATE_IN_ID:x}
    movs    r2, #0
gstore_call:
    .short  0, 0                    /* AddParam */
    mov     r0, r4
    movw    r1, #0x{GATE_RR_ID:x}
    movs    r2, #0
gstore_call2:
    .short  0, 0                    /* AddParam */
    mov     r0, r4
    movw    r1, #0x{GATE_ACTION_ID:x}
    movs    r2, #0
gstore_call3:
    .short  0, 0                    /* AddParam */
    mov     r0, r4
    movw    r1, #0x{GATE_HOLD_ID:x}
    movs    r2, #1                  /* Roll */
gstore_call4:
    .short  0, 0                    /* AddParam */
    mov     r0, r4
    movw    r1, #0x{GATE_CV_ID:x}
    movs    r2, #0
gstore_call5:
    .short  0, 0                    /* AddParam */
    mov     r0, r4
    movw    r1, #0x{REC_IN_ID:x}
    movs    r2, #0
gstore_call6:
    .short  0, 0                    /* AddParam */
    mov     r0, r4
    movw    r1, #0x{CLIP_ROW_ID:x}
    movs    r2, #0
gstore_call7:
    .short  0, 0                    /* AddParam */
    pop     {{r0, r1, r2, r3, r12, pc}}

grow:                               /* the Clip voice's setter, ids above 0xd5 (audio task): r4 = id, */
    push    {{r0, r1, r2, r3, r12, lr}} /* r5 = the voice, r1 = the clock (hook B's r9), r6 = the event */
    mov     r0, r5
grow_k:
    .short  0, 0                    /* bl clip_kind(voice): b25, a load posts every pad's settings */
    pop     {{r0, r1, r2, r3, r12, lr}}
    movw    r3, #0x{CLIP_ROW_ID:x}
    cmp     r4, r3
    bne     grow_stock
    mov     r0, r5
    ldr     r2, [r6, #0x10]         /* the value */
grow_c:
    .short  0, 0                    /* bl clip_row(voice, clock, value) */
grow_done:
    .short  0, 0                    /* b.w the setter's epilogue: no stock case takes 0x1ae */
grow_stock:
    movw    r3, #0x13f              /* the instruction this replaced */
grow_next:
    .short  0, 0                    /* b.w on, as stock */

gdpost:                             /* SetParam(r0 manager, r1 key, r2 id, r3 value) from the audio task: */
    push    {{r4, lr}}                /* the same event, straight into the router's list, as the ring's */
    sub     sp, #24                 /* reader puts it; never onto the ring, which can wait on itself */
    movs    r4, #0x39
    str     r4, [sp]
    movs    r4, #0
    str     r4, [sp, #4]
    str     r1, [sp, #8]
    str     r2, [sp, #12]
    str     r3, [sp, #16]
    str     r4, [sp, #20]
    movw    r0, #{MANAGER & 0xffff}
    movt    r0, #{MANAGER >> 16}
    movw    r4, #0x{ENGINE_PTR:x}
    ldr     r0, [r0, r4]            /* the engine */
    mov     r1, sp
gdpost_call:
    .short  0, 0                    /* bl MIDI_POST_FN(engine, &event): its list 0x400 */
    add     sp, #24
    pop     {{r4, pc}}

gsstore:                            /* r0 = the global store: Rec Selected = Off, as T's tstore */
    push    {{r0, r1, r2, r3, r12, lr}}
    movw    r1, #0x{REC_SEL_ID:x}
    movs    r2, #0
gsstore_call:
    .short  0, 0                    /* AddParam */
    pop     {{r0, r1, r2, r3, r12, lr}}
gsstore_next:
    .short  0, 0

gspost:                             /* PostSetParam(r0 mgr, r1 key, r2 id, r3 value): boot's apply-all */
    movw    r12, #0x{REC_SEL_ID:x}
    cmp     r2, r12
    beq     gsmine
gspost_next:
    .short  0, 0
gsedit:                             /* the same, from a live edit on the Settings screen */
    movw    r12, #0x{REC_SEL_ID:x}
    cmp     r2, r12
    beq     gsmine
gsedit_next:
    .short  0, 0
gsmine:                             /* Rec Selected: kept for rec_gate, NOT posted to the engine */
    push    {{r0, r1, r2, r3, r4, lr}}
    mov     r4, r3
    cmp     r4, #{len(REC_VALUES) - 1}
    bls     gs_keep
    movw    r0, #{GLOBAL_STORE & 0xffff}  /* out of range: Off, and in the store too, as Keep CCs */
    movt    r0, #{GLOBAL_STORE >> 16}
    movw    r1, #0x{REC_SEL_ID:x}
    movs    r2, #0
gs_set:
    .short  0, 0                    /* bl SetParam */
    movs    r4, #0
gs_keep:
    bl      ginit                   /* first: its power-on clear must not undo this */
    movw    r0, #{REC_RAM & 0xffff}
    movt    r0, #{REC_RAM >> 16}
    strb    r4, [r0, #{RC_SEL}]
    pop     {{r0, r1, r2, r3, r4, pc}}

gcap:                               /* the router's param case, ids above 0xed: r3 = id - 0x4d, r8 = record */
    movw    r12, #0x{GATE_IN_ID - 0x4d:x}
    subs    r12, r3, r12            /* 0 Gate In, 1 Round Robin, 2 Gate Action, 3 Hold FX, 5 CV, 7 Rec In */
    cmp     r12, #{REC_IN_ID - GATE_IN_ID}
    bhi     gcap_out
    cmp     r12, #4                 /* 0x1a8: not ours */
    beq     gcap_out
    cmp     r12, #6                 /* 0x1aa: not ours */
    beq     gcap_out
    cmp     r8, #8                  /* a pad record (4 is a dummy and never read) */
    bhi     gcap_out
    ldr     r3, [sp, #0x20]         /* the address: page 0 only, as MIDI In's case */
    tst     r3, #0xff0000
    bne     gcap_out
    push    {{r0, r1, r2, lr}}
    bl      ginit                   /* keeps r12 */
    movw    r1, #{GATE2_RAM & 0xffff}
    movt    r1, #{GATE2_RAM >> 16}
    str     r5, [r1, #{GD_ROUTER}]  /* the router: Mute and Solo find a channel's pads in it */
    ldr     r1, [sp, #0x38]         /* the value, evt+0x10 */
    cmp     r12, #2
    bhs     gcap_does
    add     r0, r0, r8
    add     r0, r0, r12, lsl #3
    add     r0, r0, r12             /* + 9 for Round Robin */
    strb    r1, [r0, #{GI_GIN}]
gcap_done:
    pop     {{r0, r1, r2, lr}}
gcap_out:
    .short  0, 0                    /* b.w on to the forward, as stock */
gcap_does:                          /* r12 = 2 Gate Action, 3 Hold FX, 5 CV, 7 Rec In */
    cmp     r12, #5
    beq     gcap_cv
    cmp     r12, #{REC_IN_ID - GATE_IN_ID}
    beq     gcap_rec
    movw    r0, #{GATE2_RAM & 0xffff}
    movt    r0, #{GATE2_RAM >> 16}
    add     r0, r0, r8
    cmp     r12, #2
    ite     eq
    strbeq  r1, [r0, #{GD_DOES}]
    strbne  r1, [r0, #{GD_HOLD}]
    b       gcap_done
gcap_cv:
    movw    r0, #{GATE3_RAM & 0xffff}
    movt    r0, #{GATE3_RAM >> 16}
    add     r0, r0, r8
    strb    r1, [r0, #{GC_CV}]
    movw    r0, #{SC_RAM & 0xffff}  /* b20: an edit forgets the pad's last pick and marks */
    movt    r0, #{SC_RAM >> 16}     /* its next one to pop up, once */
    add     r2, r0, r8
    movs    r1, #0
    strb    r1, [r2, #{SC_CVPICK}]
    ldrh    r1, [r0, #{SC_CVSHOW}]
    movs    r2, #1
    lsl     r2, r2, r8
    orr     r1, r1, r2
    strh    r1, [r0, #{SC_CVSHOW}]
    b       gcap_done
gcap_rec:
    movw    r0, #{REC_RAM & 0xffff}
    movt    r0, #{REC_RAM >> 16}
    add     r0, r0, r8
    strb    r1, [r0, #{RC_IN}]
    b       gcap_done

gon:                                /* rise: r0 router, r1, r2 input, r3; [sp] vel, ctx, flag */
    ldrh    r12, [sp, #0x2c]        /* an on-screen press: stock */
    cmp     r12, #0
    bne     gon_stock
    bic     r12, r2, #3             /* inputs are 0x000-0x003 and 0x100-0x103 */
    cmp     r12, #0x100
    it      ne
    cmpne   r12, #0
    bne     gon_stock
    push    {{r4, r5, r6, r7, r8, r9, r10, r11, lr}}
    sub     sp, #28                 /* 3 stack args, the turn, a count, the buttons pressed; 8-byte aligned */
    ldr     r4, [sp, #64]
    str     r4, [sp]
    ldr     r4, [sp, #68]
    str     r4, [sp, #4]
    ldr     r4, [sp, #72]
    str     r4, [sp, #8]
    movs    r4, #0
    str     r4, [sp, #20]
    bl      gsetup                  /* r4-r7 = r0-r3, r8 = input record, r9 = state */
    movs    r1, #1
    bl      skgate                  /* the sidechain: this input is high */
    mov     r0, r8
    ldr     r1, [sp, #4]            /* the context */
    bl      grecgate                /* Rec In, Rec Selected: their posts before any pad plays */
    movs    r10, #0                 /* the Round Robin pads it reaches */
    movs    r11, #0
    movs    r3, #0                  /* their values, ORed: bit 1 = any Random */
gon_count:
    bl      gmatch                  /* r0-r2 only */
    bne     gon_cnext
    add     r0, r9, r11
    ldrb    r0, [r0, #{GI_RR}]
    cbz     r0, gon_cnext
    mov     r12, r0
    bl      gdoes                   /* r0 only */
    cbnz    r0, gon_cnext           /* a button pad never takes a turn */
    orr     r3, r3, r12
    add     r10, r10, #1
gon_cnext:
    add     r11, r11, #1
    cmp     r11, #9
    blo     gon_count
    add     r1, r9, r8
    ldrb    r2, [r1, #{GI_CTRIN}]
    cmp     r10, #0
    beq     gon_turn
    tst     r3, #2
    bne     gon_rand
    udiv    r3, r2, r10
    mls     r2, r3, r10, r2         /* this rise's turn */
    adds    r3, r2, #1
    cmp     r3, r10
    it      hs
    movhs   r3, #0
    strb    r3, [r1, #{GI_CTRIN}]   /* the next rise's */
    b       gon_turn
gon_rand:                           /* Random: CTRIN holds the turn that played last */
    mov     r0, r10
    mov     r3, r2
    bl      gpick                   /* r3 = this rise's turn; keeps r0-r2 */
    strb    r3, [r1, #{GI_CTRIN}]
    mov     r2, r3
gon_turn:
    str     r2, [sp, #12]
    movs    r0, #0
    str     r0, [sp, #16]           /* Round Robin pads passed so far */
    movs    r10, #0                 /* the pads fired */
    movs    r11, #0
gon_loop:
    bl      gmatch                  /* r2 = pad r11's address if it answers r8, else flags NE */
    bne     gon_next
    bl      gdoes                   /* r0 only */
    cbnz    r0, gon_btn
    add     r0, r9, r11
    ldrb    r0, [r0, #{GI_RR}]
    cbz     r0, gon_fire            /* Off: every time */
    ldr     r0, [sp, #16]
    adds    r1, r0, #1
    str     r1, [sp, #16]
    ldr     r1, [sp, #12]
    cmp     r0, r1
    bne     gon_next                /* On: on its turn only */
gon_fire:
    mov     r0, r4
    mov     r1, r5
    mov     r3, r7
gon_call:
    .short  0, 0                    /* bl 0x080aaf78 */
    bl      gbit
    orr     r10, r10, r0
    b       gon_next
gon_btn:                            /* Gate Action Hold FX: hold it, don't play */
    bl      ghold                   /* r0 = the Hold FX's CC: the pad's, or Random's pick; keeps r2 */
    movw    r1, #{GATE2_RAM & 0xffff}
    movt    r1, #{GATE2_RAM >> 16}
    add     r1, r1, r11
    strb    r0, [r1, #{GD_HCC}]     /* what its release lets go */
    cbz     r0, gon_held            /* b24, Off: holds nothing, plays nothing, but counts as held, */
    ldr     r3, [sp, #4]            /* so its fall sends no stock release (grelease skips CC 0) */
    movw    r1, #0x3f80             /* 127, widened to 14 bits as a CC arrives */
    bl      gbtn
gon_held:
    bl      gbit
    ldr     r1, [sp, #20]
    orr     r1, r1, r0
    str     r1, [sp, #20]
gon_next:
    add     r11, r11, #1
    cmp     r11, #9
    blo     gon_loop
    add     r0, r9, r8
    strb    r10, [r0, #{GI_FIRED}]  /* its release goes to exactly these */
    movw    r0, #{GATE2_RAM & 0xffff}
    movt    r0, #{GATE2_RAM >> 16}
    add     r0, r0, r8
    ldrb    r1, [r0, #{GD_BHELD}]
    ldr     r2, [sp, #20]
    orr     r1, r1, r2              /* and these buttons, with any a lost fall left held */
    strb    r1, [r0, #{GD_BHELD}]
    add     sp, #28
    pop     {{r4, r5, r6, r7, r8, r9, r10, r11, pc}}
gon_stock:
    .short  0, 0                    /* b.w 0x080aaf78 */

goff:                               /* fall: r0 router, r1, r2 input, r3; [sp] ctx, flag */
    ldrh    r12, [sp, #0x2c]
    cmp     r12, #0
    bne     goff_stock
    bic     r12, r2, #3
    cmp     r12, #0x100
    it      ne
    cmpne   r12, #0
    bne     goff_stock
    push    {{r4, r5, r6, r7, r8, r9, r10, r11, lr}}
    sub     sp, #12                 /* 8-byte aligned, as gon */
    ldr     r4, [sp, #48]
    str     r4, [sp]
    ldr     r4, [sp, #52]
    str     r4, [sp, #4]
    bl      gsetup
    movs    r1, #0
    bl      skgate                  /* the sidechain: this input is low */
    ldr     r3, [sp]                /* the context */
    bl      grelease                /* r0 = the buttons it let go */
    str     r0, [sp, #8]
    add     r0, r9, r8
    ldrb    r10, [r0, #{GI_FIRED}]
    movs    r1, #0
    strb    r1, [r0, #{GI_FIRED}]
    cmp     r10, #0
    bne     goff_go
    ldr     r0, [sp, #8]
    cmp     r0, #0
    bne     goff_done               /* its rise held buttons and played nothing */
    mov     r0, r8                  /* nothing fired (a Gate Funct input): stock's */
    bl      gres                    /* release, if the input's own pad still answers it */
    cmp     r0, r8
    bne     goff_done
    mov     r11, r8
    bl      gbit
    mov     r10, r0
goff_go:
    movs    r11, #0
goff_loop:
    cmp     r11, #4
    beq     goff_next
    bl      gbit
    tst     r10, r0
    beq     goff_next
    bl      gaddr
    mov     r0, r4
    mov     r1, r5
    mov     r3, r7
goff_call:
    .short  0, 0                    /* bl 0x080ab118 */
goff_next:
    add     r11, r11, #1
    cmp     r11, #9
    blo     goff_loop
goff_done:
    add     sp, #12
    pop     {{r4, r5, r6, r7, r8, r9, r10, r11, pc}}
goff_stock:
    .short  0, 0                    /* b.w 0x080ab118 */

mon:                                /* MIDI In loop, note-on post: r0 ctx, r1 evt, r2 pad; */
    push    {{r0, r1, r2, r3, r4, r7, r8, lr}}  /* sl record, r5 router, r6 the MIDI event, sb note */
    bl      mpad                    /* r4 = record, r7 = channel, r8 = state; NE: stock */
    bne     mon_post
    bl      mscan                   /* r0 = Round Robin pads on the channel, r1 = this one's place, */
    add     r2, r8, r7              /* r12 = their values ORed */
    ldrb    r3, [r2, #{GI_CTRCH}]
    tst     r12, #2
    bne     mon_rand
    udiv    r12, r3, r0
    mls     r3, r12, r0, r3         /* this note's turn */
    sub     r12, r0, #1
    cmp     r1, r12
    bne     mon_turn
    adds    r12, r3, #1             /* the last of them: the next note's turn */
    cmp     r12, r0
    it      hs
    movhs   r12, #0
    strb    r12, [r2, #{GI_CTRCH}]
    b       mon_turn
mon_rand:                           /* Random: CTRCH holds this note's turn, chosen at the */
    cbnz    r1, mon_rturn           /* first Round Robin pad the loop reaches */
    bl      gpick                   /* keeps r0-r2 */
    strb    r3, [r2, #{GI_CTRCH}]
mon_rturn:
    ldrb    r3, [r2, #{GI_CTRCH}]
    udiv    r12, r3, r0
    mls     r3, r12, r0, r3         /* in range even after an edit */
mon_turn:
    cmp     r1, r3
    bne     mon_skip
    bl      mhold                   /* remember which pad played this note */
mon_post:
    pop     {{r0, r1, r2, r3, r4, r7, r8, lr}}
mon_stock:
    .short  0, 0                    /* b.w 0x080a83a4, the post, back to the loop */
mon_skip:
    pop     {{r0, r1, r2, r3, r4, r7, r8, lr}}
mon_next:
    .short  0, 0                    /* b.w the loop's next record */

moff:                               /* MIDI In loop, note-off post: as mon */
    push    {{r0, r1, r2, r3, r4, r7, r8, lr}}
    bl      mpad
    bne     moff_post
    bl      mscan
    sub     r12, r0, #1             /* r12: this is the last Round Robin pad */
    subs    r12, r1, r12
    bl      mfind                   /* r0 = the note's slot, or 0; keeps r12 */
    cbz     r0, moff_post           /* not one a turn played: stock */
    ldrb    r2, [r0, #2]
    cmp     r12, #0
    bne     moff_mine
    strb    r12, [r0, #3]           /* the last pad: the slot is free again */
moff_mine:
    cmp     r2, r4
    bne     moff_skip
moff_post:
    pop     {{r0, r1, r2, r3, r4, r7, r8, lr}}
moff_stock:
    .short  0, 0                    /* b.w 0x080a83a4 */
moff_skip:
    pop     {{r0, r1, r2, r3, r4, r7, r8, lr}}
moff_next:
    .short  0, 0                    /* b.w the loop's next record */

mpad:                               /* sl's record if a Round Robin pad on channel 0-15: EQ */
    sub     r4, sl, r5
    cmp     r4, #96
    bhi     mpad_no
    movs    r3, #12
    udiv    r4, r4, r3
    cmp     r4, #4
    beq     mpad_no
    ldr     r7, [r6, #8]
    cmp     r7, #15
    bhi     mpad_no
    push    {{lr}}
    bl      ginit
    pop     {{lr}}
    mov     r8, r0
    add     r0, r0, r4
    ldrb    r0, [r0, #{GI_RR}]
    cbz     r0, mpad_no
    cmp     r0, r0                  /* EQ: On or Random */
    bx      lr
mpad_no:
    cmp     r5, #0                  /* NE: the router is never 0 */
    bx      lr

mscan:                              /* r0 = Round Robin pads with MIDI In on r7, r1 = how many precede r4, */
    movs    r0, #0                  /* r12 = their values ORed */
    movs    r1, #0
    movs    r2, #0
    mov     r12, r0
mscan_loop:
    cmp     r2, #4
    beq     mscan_next
    add     r3, r8, r2
    ldrb    r3, [r3, #{GI_RR}]
    cbz     r3, mscan_next
    add     r3, r2, r2, lsl #1
    add     r3, r5, r3, lsl #2
    ldr     r3, [r3, #0x24]         /* MIDI In: 0 None, else channel + 1, as the loop reads it */
    subs    r3, #1
    cmp     r3, r7
    bne     mscan_next
    add     r3, r8, r2
    ldrb    r3, [r3, #{GI_RR}]
    orr     r12, r12, r3
    cmp     r2, r4
    it      lo
    addlo   r1, #1
    adds    r0, #1
mscan_next:
    adds    r2, #1
    cmp     r2, #9
    blo     mscan_loop
    bx      lr

mfind:                              /* r0 = the held slot for channel r7, note sb, or 0; keeps r1, r12 */
    add     r0, r8, #{GI_HELD}
    add     r2, r0, #{4 * GI_SLOTS}
mfind_loop:
    ldrb    r3, [r0, #3]
    cbz     r3, mfind_next
    ldrb    r3, [r0]
    cmp     r3, r7
    bne     mfind_next
    ldrb    r3, [r0, #1]
    cmp     r3, r9
    it      eq
    bxeq    lr
mfind_next:
    adds    r0, #4
    cmp     r0, r2
    blo     mfind_loop
    movs    r0, #0
    bx      lr

mhold:                              /* hold (r7, sb, r4): its slot, a free one, or the oldest reused */
    push    {{lr}}
    bl      mfind
    pop     {{lr}}
    cbnz    r0, mhold_put
    add     r0, r8, #{GI_HELD}
    add     r2, r0, #{4 * GI_SLOTS}
mhold_free:
    ldrb    r3, [r0, #3]
    cbz     r3, mhold_put
    adds    r0, #4
    cmp     r0, r2
    blo     mhold_free
    ldrb    r3, [r8, #{GI_NEXT}]
    adds    r2, r3, #1
    and     r2, r2, #{GI_SLOTS - 1}
    strb    r2, [r8, #{GI_NEXT}]
    add     r0, r8, #{GI_HELD}
    add     r0, r0, r3, lsl #2
mhold_put:
    strb    r7, [r0]
    strb    r9, [r0, #1]
    strb    r4, [r0, #2]
    movs    r3, #1
    strb    r3, [r0, #3]
    bx      lr

mcc:                                /* at 0x08093f14, the head of the CC hooks: CC 94 Mute and */
    ldrb    r3, [sp, #{MSG_TYPE_SP:#x}]  /* CC 95 Solo, then on down the chain; r2, r3 are dead */
    cmp     r3, #7                      /* here (pmidi). 7: a CC */
    bne     mnote
    ldr     r3, [sp, #{MSG_CC_SP:#x}]
    sub     r3, r3, #{CC_BEATSYNC}
    cmp     r3, #3
    bls     mdly                    /* CC 108-111: noted for Keep CCs, then on down */
    ldr     r3, [sp, #{MSG_CC_SP:#x}]
    sub     r3, r3, #{GATE_CC_MUTE}
    cmp     r3, #1
    bhi     mcc_next
    push    {{r0, r1, r4, r5, r6, r7, r8, r9, r10, r11, r12, lr}}
    mrs     r12, apsr
    push    {{r12}}
    sub     sp, #4                  /* 56: 8-byte aligned */
    ldr     r6, [sp, #{MSG_CHAN_SP + 56:#x}]
    ldr     r7, [sp, #{MSG_CC_SP + 56:#x}]
    ldr     r8, [sp, #{MSG_VAL_SP + 56:#x}]
    cmp     r6, #15
    bhi     mcc_out
    bl      ginit
    movw    r9, #{GATE2_RAM & 0xffff}
    movt    r9, #{GATE2_RAM >> 16}
    ldr     r10, [r9, #{GD_ROUTER}]
    cmp     r10, #0
    beq     mcc_out                 /* no preset has loaded since power-on */
    movs    r4, #0                  /* the pads on the channel */
    movs    r11, #0
mcc_scan:
    cmp     r11, #4
    beq     mcc_snext
    add     r3, r11, r11, lsl #1
    add     r3, r10, r3, lsl #2
    ldr     r3, [r3, #0x24]         /* MIDI In: 0 None, else channel + 1 */
    subs    r3, #1
    cmp     r3, r6
    bne     mcc_snext
    bl      gbit
    orr     r4, r4, r0
mcc_snext:
    add     r11, r11, #1
    cmp     r11, #9
    blo     mcc_scan
    cmp     r4, #0
    beq     mcc_out
    ubfx    r8, r8, #13, #1         /* 64 and up: on */
    ldrb    r5, [r9, #{GD_SOLO}]
    cbnz    r5, mcc_soloing
    bl      msnap                   /* nothing soloed: the pads' own mutes are what the module shows */
    strb    r0, [r9, #{GD_OWNM}]
mcc_soloing:
    ldrb    r0, [r9, #{GD_OWNM}]
    cmp     r7, #{GATE_CC_MUTE}
    bne     mcc_solo
    cmp     r8, #0
    ite     ne
    orrne   r0, r0, r4
    biceq   r0, r0, r4
    strb    r0, [r9, #{GD_OWNM}]
    b       mcc_apply
mcc_solo:
    cmp     r8, #0
    ite     ne
    orrne   r5, r5, r4
    biceq   r5, r5, r4
    strb    r5, [r9, #{GD_SOLO}]
mcc_apply:
    ldrb    r4, [r9, #{GD_OWNM}]
    ldrb    r5, [r9, #{GD_SOLO}]
    cmp     r5, #0
    it      ne
    mvnne   r4, r5                  /* soloing: every pad not soloed */
    bl      mapply
mcc_out:
    add     sp, #4
    pop     {{r12}}
    msr     apsr_nzcvq, r12
    pop     {{r0, r1, r4, r5, r6, r7, r8, r9, r10, r11, r12, lr}}
mcc_next:
    .short  0, 0                    /* b.w the chain's head before this one */

mdly:                               /* r3 = CC - 108: its 14-bit value and a touched flag; r2, r3, r12 */
    movw    r2, #{GATE3_RAM & 0xffff}
    movt    r2, #{GATE3_RAM >> 16}
    ldr     r12, [sp, #{MSG_VAL_SP:#x}]
    add     r2, r2, r3, lsl #1
    strh    r12, [r2, #{GC_DVAL}]
    movw    r2, #{GATE3_RAM & 0xffff}
    movt    r2, #{GATE3_RAM >> 16}
    add     r2, r2, r3
    movs    r12, #1
    strb    r12, [r2, #{GC_DTOUCH}]
    b       mcc_next

mnote:                              /* r3 = the type: a note on channel 16 is the sidechain's MIDI key */
    subs    r3, #5                  /* 0 note-on, 1 note-off */
    cmp     r3, #1
    bhi     mcc_next
    ldr     r2, [sp, #{MSG_CHAN_SP:#x}]
    cmp     r2, #{SC_MIDI_CHAN}
    bne     mcc_next
    push    {{r0, r1}}                /* the chain's arguments: back before it runs */
    movw    r2, #{SC_RAM & 0xffff}
    movt    r2, #{SC_RAM >> 16}
    ldr     r0, [r2]
    movw    r1, #{SC_MAGIC & 0xffff}
    movt    r1, #{SC_MAGIC >> 16}
    cmp     r0, r1
    bne     mn_out                  /* not seeded yet: sc_key seeds it every block */
    ldrb    r1, [r2, #{SC_MHELD}]
    cbnz    r3, mn_off
    ldr     r0, [sp, #{MSG_VAL_SP + 8:#x}]   /* the velocity; +8, our push */
    cbz     r0, mn_off              /* note-on at 0: a note-off */
    cmp     r0, #127
    it      hi
    lsrhi   r0, r0, #7              /* widened as a CC is: back to 7 bits */
    strb    r0, [r2, #{SC_MVEL}]
    cmp     r1, #255
    it      lo
    addlo   r1, #1
    strb    r1, [r2, #{SC_MHELD}]
    b       mn_out
mn_off:
    cbz     r1, mn_out
    subs    r1, #1
    strb    r1, [r2, #{SC_MHELD}]
mn_out:
    pop     {{r0, r1}}
    b       mcc_next

mrec:                               /* r0 = pad r11's record's "muted" byte; r0-r3 */
    push    {{lr}}
    bl      gaddr                   /* r2 = (row << 8) | column */
    pop     {{lr}}
    and     r0, r2, #3
    lsrs    r1, r2, #8
    movs    r3, #120
    mul     r1, r1, r3
    movs    r3, #24
    mla     r1, r0, r3, r1
    movw    r0, #{(GATE_PADREC + GATE_PADREC_ACTIVE) & 0xffff}
    movt    r0, #{(GATE_PADREC + GATE_PADREC_ACTIVE) >> 16}
    add     r0, r0, r1
    bx      lr

msnap:                              /* r0 = the pads the module shows muted, as gbit numbers them */
    push    {{r4, r11, lr}}
    movs    r4, #0
    movs    r11, #0
ms_loop:
    cmp     r11, #4
    beq     ms_next
    bl      mrec
    ldrb    r0, [r0]
    cbz     r0, ms_next             /* 1: muted (b19, traced: 0x47 = 1 is 0x080a5e9e's silent buffer) */
    bl      gbit
    orr     r4, r4, r0
ms_next:
    add     r11, r11, #1
    cmp     r11, #9
    blo     ms_loop
    mov     r0, r4
    pop     {{r4, r11, pc}}

mapply:                             /* r4 = the pads to mute: post each pad whose state differs, */
    push    {{r5, r6, r11, lr}}       /* as the Mixer's Mute Mode does. From the audio task (mcc): */
    movs    r5, #0                  /* straight to the router (gdpost) */
    b       map_go
mapply_ui:                          /* the same from the UI thread (mload): through SetParam's ring */
    push    {{r5, r6, r11, lr}}
    movs    r5, #1
map_go:
    movs    r11, #0
map_loop:
    cmp     r11, #4
    beq     map_next
    bl      gbit
    tst     r4, r0
    ite     ne
    movne   r6, #1                  /* 1: muted, as the Mixer posts it */
    moveq   r6, #0
    bl      mrec
    ldrb    r3, [r0]
    cmp     r3, r6
    beq     map_next
    strb    r6, [r0]                /* what the Mixer draws */
    bl      gaddr
    sub     sp, #8
    movs    r3, #0
    str     r3, [sp]
    str     r3, [sp, #4]
    mov     r1, r2
    movw    r0, #{MANAGER & 0xffff}
    movt    r0, #{MANAGER >> 16}
    movs    r2, #{GATE_P_ACTIVE}
    mov     r3, r6
    cbnz    r5, map_ring
    bl      gdpost                  /* b21: as 0x0807e9ec's SetParam, straight to the router: never waits */
    b       map_posted
map_ring:
map_setp:
    .short  0, 0                    /* bl cmd39 SetParam, as 0x0807e9ec */
map_posted:
    add     sp, #8
map_next:
    add     r11, r11, #1
    cmp     r11, #9
    blo     map_loop
    pop     {{r5, r6, r11, pc}}

skgate:                             /* r1 = 1 high / 0 low: input r8 in the sidechain's gates; r0-r3 */
    movw    r2, #{SC_RAM & 0xffff}
    movt    r2, #{SC_RAM >> 16}
    ldr     r3, [r2]
    movw    r0, #{SC_MAGIC & 0xffff}
    movt    r0, #{SC_MAGIC >> 16}
    cmp     r3, r0
    bne     skg_out                 /* not seeded yet: sc_key seeds it every block */
    cmp     r8, #4
    ite     hi
    subhi   r0, r8, #1
    movls   r0, r8                  /* records 0-3, 5-8: bits 0-7, as gbit */
    movs    r3, #1
    lsl     r3, r3, r0
    ldrb    r0, [r2, #{SC_GATES}]
    cmp     r1, #0
    ite     ne
    orrne   r0, r0, r3
    biceq   r0, r0, r3
    strb    r0, [r2, #{SC_GATES}]
skg_out:
    bx      lr

skey:                               /* hook S, at 0x080b9b68: r0 = the RMS ring, r5 = frames, r7 = msg */
    push    {{r0, r1, r2, r3, r12, lr}}
    vpush   {{s1-s15}}
    sub     sp, #4                  /* 88: 8-byte aligned */
    mov     r0, r7
    mov     r1, r5
skey_c:
    .short  0, 0                    /* bl sc_key: s0 = the key's RMS, or -1 */
    add     sp, #4
    vpop    {{s1-s15}}
    vcmp.f32 s0, #0
    vmrs    APSR_nzcv, fpscr
    blt     skey_stock
    pop     {{r0, r1, r2, r3, r12, pc}}
skey_stock:
    pop     {{r0, r1, r2, r3, r12, lr}}
skey_rms:
    .short  0, 0                    /* b.w 0x080a39d8: Self with no filter, stock */

mfinal:                             /* both FinalizeBankLoading sites (UI thread): a preset loaded */
    push    {{r4, lr}}
    push    {{r0, r1, r2, r3}}        /* b21: Keep CCs ON, each pad's Clip Tempo into the new stores, */
mfinal_keep:                        /* before Finalize posts them */
    .short  0, 0                    /* bl clip_row_keep */
    pop     {{r0, r1, r2, r3}}
mfinal_call:
    .short  0, 0                    /* bl the previous head, r0 as given */
    push    {{r0, r1, r2, r3}}        /* as it left them, flags too, as Keep CCs' pfinal */
    mrs     r3, apsr
    push    {{r3, r5, r6, r11}}
    bl      mload
    pop     {{r3, r5, r6, r11}}
    msr     apsr_nzcvq, r3
    pop     {{r0, r1, r2, r3}}
    pop     {{r4, pc}}

mload:                              /* Keep CCs ON: the same pad positions muted or soloed again; */
    push    {{r7, lr}}                /* OFF: forgotten. 8-byte aligned for SetParam */
    bl      ginit
    movw    r7, #{GATE2_RAM & 0xffff}
    movt    r7, #{GATE2_RAM >> 16}
    movw    r0, #{KEEP_RAM & 0xffff}
    movt    r0, #{KEEP_RAM >> 16}
    ldr     r0, [r0, #{KEEP_MODE_OFF}]
    movw    r1, #{KEEP_ON & 0xffff}
    movt    r1, #{KEEP_ON >> 16}
    cmp     r0, r1
    beq     mload_keep
    movs    r0, #0
    strb    r0, [r7, #{GD_OWNM}]
    strb    r0, [r7, #{GD_SOLO}]
    movw    r1, #{GATE3_RAM & 0xffff}
    movt    r1, #{GATE3_RAM >> 16}
    str     r0, [r1, #{GC_DTOUCH}]  /* and the delay's toggles */
    pop     {{r7, pc}}
mload_keep:
    bl      mdlyload                /* the delay's toggles, first */
    ldrb    r4, [r7, #{GD_OWNM}]
    ldrb    r0, [r7, #{GD_SOLO}]
    orrs    r1, r4, r0
    beq     mload_out               /* nothing muted or soloed: the new preset as it loaded */
    cmp     r0, #0
    it      ne
    mvnne   r4, r0                  /* soloing: every pad not soloed */
    movs    r11, #0
mload_mark:                         /* every pad posted: its record may still hold the old preset's */
    cmp     r11, #4
    beq     mload_mnext
    bl      mrec
    movs    r1, #2                  /* neither muted (1) nor plays (0) */
    strb    r1, [r0]
mload_mnext:
    add     r11, r11, #1
    cmp     r11, #9
    blo     mload_mark
    bl      mapply_ui               /* the UI thread: through SetParam's ring, as the Mixer */
mload_out:
    pop     {{r7, pc}}

gcv:                                /* r0 = pad record r11's CV row (0 Off, 1-8 Hold FX n, 9-16 Flip n); r0 only */
    movw    r0, #{GATE3_RAM & 0xffff}
    movt    r0, #{GATE3_RAM >> 16}
    add     r0, r0, r11
    ldrb    r0, [r0, #{GC_CV}]
    cmp     r0, #{len(GATE_CV_VALUES) - 1}
    it      hi
    movhi   r0, #0
    bx      lr

gcvpick:                            /* r0 = input 1-8, r1 = how many, r2 = pad record: r0 = the band; */
    push    {{r1, r2, r3, r12, lr}}   /* keeps r1-r3, r12 and s0-s15 (the router's) */
    vpush   {{s0-s15}}
    sub     sp, #4                  /* 88: 8-byte aligned */
gcvp_c:
    .short  0, 0                    /* bl cv_pick */
    add     sp, #4
    vpop    {{s0-s15}}
    pop     {{r1, r2, r3, r12, pc}}

grecgate:                           /* r0 = input record, r1 = context: rec_gate; keeps r1-r3, r12 and */
    push    {{r1, r2, r3, r12, lr}}   /* s0-s15 (the router's), as gcvpick */
    vpush   {{s0-s15}}
    sub     sp, #4                  /* 88: 8-byte aligned */
grecg_c:
    .short  0, 0                    /* bl rec_gate */
    add     sp, #4
    vpop    {{s0-s15}}
    pop     {{r1, r2, r3, r12, pc}}

mdlyload:                           /* Keep CCs ON: each delay toggle sent since power-on, posted */
    push    {{r4, r5, r6, lr}}        /* again as hook C posts it; 8-byte aligned */
    movs    r4, #0
mdl_loop:
    movw    r5, #{GATE3_RAM & 0xffff}
    movt    r5, #{GATE3_RAM >> 16}
    add     r0, r5, r4
    ldrb    r0, [r0, #{GC_DTOUCH}]
    cbz     r0, mdl_next
    add     r0, r5, r4, lsl #1
    ldrh    r3, [r0, #{GC_DVAL}]
    adr.w   r0, gdlyp
    ldrb    r2, [r0, r4]            /* the delay's parameter */
    cmp     r4, #3
    beq     mdl_width
    cmp.w   r3, #{BOOL_THRESHOLD}
    ite     lt
    movlt   r3, #0
    movge   r3, #1
    b       mdl_post
mdl_width:
    lsrs    r3, r3, #7
    movw    r1, #{CC7_TO_1000_MUL}
    mul     r3, r3, r1
    lsrs    r3, r3, #{CC7_TO_1000_SHIFT}
mdl_post:
    sub     sp, #8
    movs    r0, #0
    str     r0, [sp]
    str     r0, [sp, #4]
    movw    r0, #{MANAGER & 0xffff}
    movt    r0, #{MANAGER >> 16}
    movw    r1, #{DELAY_KEY & 0xffff}
    movt    r1, #{DELAY_KEY >> 16}
mdl_setp:
    .short  0, 0                    /* bl cmd39 SetParam, as hook C's csetp */
    add     sp, #8
mdl_next:
    adds    r4, #1
    cmp     r4, #4
    blo     mdl_loop
    pop     {{r4, r5, r6, pc}}

gdoes:                              /* r0 = pad record r11's Gate Action (0 = Play); r0 only */
    push    {{r1, r2}}
    movw    r1, #{GATE2_RAM & 0xffff}
    movt    r1, #{GATE2_RAM >> 16}
    add     r0, r1, r11
    ldrb    r0, [r0, #{GD_DOES}]
    cmp     r0, #{len(GATE_ACTION_VALUES) - 1}
    it      hi
    movhi   r0, #0                  /* not a value it has: Play */
    ldrb    r1, [r1, #{GD_NOTCLIP}]
    cmp     r11, #4                 /* gbit's numbering: records 5-8 are pads 4-7 */
    ite     hi
    subhi   r2, r11, #1
    movls   r2, r11
    lsrs    r1, r1, r2
    tst     r1, #1
    it      ne
    movne   r0, #0                  /* b25: not a Clip pad: Play, whatever the hidden row says */
    pop     {{r1, r2}}
    bx      lr

ghold:                              /* r0 = the CC pad r11's Hold FX holds, 0 for Off (b24); Random: a */
    push    {{r2, lr}}                /* new one, never the last; keeps r2 (the pad's address); r0, r1, r3, r12 */
    bl      gcv
    subs    r0, #1
    cmp     r0, #8
    bhs     ghold_row               /* not Hold FX n: the Hold FX row */
    adds    r0, #1
    movs    r1, #{len(GATE_HOLDS) + 1}
    mov     r2, r11                 /* for its one pop-up after the row is set; ghold keeps r2 */
    bl      gcvpick                 /* input n's voltage: 0 Off, 1 .. 7 */
    mov     r3, r0
    b       ghold_cc
ghold_row:
    movw    r1, #{GATE2_RAM & 0xffff}
    movt    r1, #{GATE2_RAM >> 16}
    add     r1, r1, r11
    ldrb    r3, [r1, #{GD_HOLD}]
    cmp     r3, #{len(GATE_HOLDS) + 1}
    blo     ghold_cc                /* Off, or one of the seven */
    bne     ghold_roll              /* not a value it has: Roll */
    ldrb    r3, [r1, #{GD_HLAST}]   /* Random */
    movs    r0, #{len(GATE_HOLDS)}
    bl      gpick                   /* r3 = 0 .. 6, never the last; keeps r0-r2 */
    strb    r3, [r1, #{GD_HLAST}]
    adds    r3, #1                  /* past Off */
    b       ghold_cc
ghold_roll:
    movs    r3, #1
ghold_cc:
    adr.w   r0, ghcc
    ldrb    r0, [r0, r3]
    pop     {{r2, pc}}

gbtn:                               /* post CC r0 = value r1 to address r2, context r3, as the */
    push    {{r4, r5, lr}}            /* router's CC fan-out: r4 router, r11 the pad's record */
    sub     sp, #28                 /* the 24-byte event; 8-byte aligned */
    movs    r5, #7
    str     r5, [sp]                /* type 7: a CC */
    movs    r5, #0
    str     r5, [sp, #4]
    str     r0, [sp, #12]
    orr     r1, r1, #{GATE_CC_MARK}  /* b16: a gate sent it; Clip Tempo shows no pop-up */
    str     r1, [sp, #16]
    str     r5, [sp, #20]
    add     r5, r11, r11, lsl #1
    add     r5, r4, r5, lsl #2
    ldr     r5, [r5, #0x24]         /* its MIDI In: 0 None, else channel + 1 */
    subs    r5, #1
    it      lo
    movlo   r5, #0
    str     r5, [sp, #8]            /* the channel, as a controller's CC carries it */
    mov     r0, r3
    mov     r1, sp
gbtn_post:
    .short  0, 0                    /* bl 0x080a83a4 */
    add     sp, #28
    pop     {{r4, r5, pc}}

grelease:                           /* r3 = context: let go of what input r8's rise held; r0 = that mask */
    push    {{r6, r10, r11, lr}}
    mov     r6, r3
    movw    r0, #{GATE2_RAM & 0xffff}
    movt    r0, #{GATE2_RAM >> 16}
    add     r0, r0, r8
    ldrb    r10, [r0, #{GD_BHELD}]
    movs    r1, #0
    strb    r1, [r0, #{GD_BHELD}]
    movs    r11, #0
grel_loop:
    cmp     r11, #4
    beq     grel_next
    bl      gbit
    tst     r10, r0
    beq     grel_next
    movw    r0, #{GATE2_RAM & 0xffff}
    movt    r0, #{GATE2_RAM >> 16}
    add     r0, r0, r11
    ldrb    r0, [r0, #{GD_HCC}]     /* the CC its press sent, whatever Gate Action says now */
    cbz     r0, grel_next
    mov     r3, r6
    bl      gaddr
    movs    r1, #0
    bl      gbtn
grel_next:
    add     r11, r11, #1
    cmp     r11, #9
    blo     grel_loop
    mov     r0, r10
    pop     {{r6, r10, r11, pc}}

gpick:                              /* r3 = a turn in [0, r0), never r3 % r0 when r0 > 1; keeps r0-r2 */
    push    {{r0, r1, r2, lr}}
    udiv    r12, r3, r0
    mls     r3, r12, r0, r3         /* the turn that played last */
    subs    r2, r0, #1              /* the other choices */
    beq     gpick_out               /* one pad: it is always its turn */
    movw    r12, #{GATE_IN_RAM & 0xffff}
    movt    r12, #{GATE_IN_RAM >> 16}
    ldr     r1, [r12, #{GI_SEED}]
    movw    r0, #0x1004
    movt    r0, #0xe000
    ldr     r0, [r0]                /* DWT's cycle counter: the moment of the hit */
    eors    r1, r1, r0
    orr     r1, r1, #1              /* never the xorshift's dead state */
    eor     r1, r1, r1, lsl #13
    eor     r1, r1, r1, lsr #17
    eor     r1, r1, r1, lsl #5
    str     r1, [r12, #{GI_SEED}]
    lsrs    r1, r1, #16
    udiv    r0, r1, r2
    mls     r1, r0, r2, r1          /* 0 .. n-2 */
    add     r3, r3, r1
    adds    r3, #1                  /* skip the last: never twice in a row */
    ldr     r0, [sp]
    cmp     r3, r0
    it      hs
    subhs   r3, r3, r0
gpick_out:
    pop     {{r0, r1, r2, pc}}

gbit:                               /* r0 = pad record r11's bit in a fired mask; uses r1 */
    cmp     r11, #4
    ite     hi
    subhi   r0, r11, #1
    movls   r0, r11
    movs    r1, #1
    lsl     r0, r1, r0
    bx      lr

gsetup:                             /* keep r0-r3, find the input's record, seed the state */
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
    mov     r7, r3
    lsrs    r8, r6, #8
    add     r8, r8, r8, lsl #2
    and     r0, r6, #3
    add     r8, r8, r0
    push    {{lr}}
    bl      ginit
    pop     {{lr}}
    mov     r9, r0
    bx      lr

gmatch:                             /* pad record r11 answers input record r8? EQ and r2 = address */
    cmp     r11, #4
    beq     gmatch_no
    push    {{lr}}
    mov     r0, r11
    bl      gres
    pop     {{lr}}
    cmp     r0, r8
    bne     gmatch_out
gaddr:                              /* r2 = ((r11 / 5) << 8) | (r11 % 5), for records 0-8 */
    cmp     r11, #5
    ite     lo
    movlo   r2, r11
    addhs   r2, r11, #0xfb
    cmp     r2, r2                  /* EQ */
gmatch_out:
    bx      lr
gmatch_no:
    cmp     r11, #0                 /* NE: r11 is 4 */
    bx      lr

gres:                               /* r0 = pad record -> the input record it answers, or 0xff */
    movw    r1, #{GATE_IN_RAM & 0xffff}
    movt    r1, #{GATE_IN_RAM >> 16}
    add     r1, r1, r0
    ldrb    r1, [r1, #{GI_GIN}]
    cbz     r1, gres_own
    cmp     r1, #8
    bhi     gres_none
    adr     r2, ginputs
    add     r2, r2, r1
    ldrb    r0, [r2, #-1]
    bx      lr
gres_none:
    movs    r0, #0xff
gres_own:
    bx      lr

ginit:                              /* r0 = the state; cleared under a magic once per power-on; r0-r3 only */
    movw    r0, #{GATE_IN_RAM & 0xffff}
    movt    r0, #{GATE_IN_RAM >> 16}
    ldr     r1, [r0]
    movw    r2, #{GATE_IN_MAGIC & 0xffff}
    movt    r2, #{GATE_IN_MAGIC >> 16}
    cmp     r1, r2
    it      eq
    bxeq    lr
    movs    r1, #0
    movs    r3, #4
ginit_clear:
    str     r1, [r0, r3]
    adds    r3, #4
    cmp     r3, #{GATE_IN_BYTES}
    blo     ginit_clear
    movw    r3, #{GATE2_RAM & 0xffff}
    movt    r3, #{GATE2_RAM >> 16}
{gclear}    movw    r3, #{GATE3_RAM & 0xffff}
    movt    r3, #{GATE3_RAM >> 16}
{g3clear}    movw    r3, #{REC_RAM & 0xffff}
    movt    r3, #{REC_RAM >> 16}
{rclear}    str     r2, [r0]
    bx      lr

    .balign 4
ginputs:
    .byte   {", ".join(str(r) for r in GATE_IN_INPUTS)}
gvalues:
    .word   {words}
rvalues:
    .word   {rwords}
dvalues:
    .word   {dwords}
hvalues:
    .word   {hwords}
cvalues:
    .word   {cwords}
qvalues:
    .word   {qwords}
svalues:
    .word   {swords}
wvalues:
    .word   {wwords}
glabel:
    .asciz  "Gate In:"
    .balign 4
gxml:
    .asciz  "gatein"
    .balign 4
rlabel:
    .asciz  "Round Robin:"
    .balign 4
rxml:
    .asciz  "roundrobin"
    .balign 4
dlabel:
    .asciz  "Gate Action:"
    .balign 4
dxml:
    .asciz  "gateaction"            /* b9: not b5-b8's "gatedoes", whose values meant otherwise */
    .balign 4
hlabel:
    .asciz  "Hold FX:"
    .balign 4
hxml:
    .asciz  "holdfx"
    .balign 4
clabel:
    .asciz  "CV Action:"            /* b19 (owner): was "CV:" */
    .balign 4
cxml:
    .asciz  "cvpick"
    .balign 4
qlabel:
    .asciz  "Rec In:"
    .balign 4
qxml:
    .asciz  "recin"
    .balign 4
slabel:
    .asciz  "Gate Rec:"
    .balign 4
sxml:
    .asciz  "recsel"
    .balign 4
wlabel:
    .asciz  "Clip Tempo:"
    .balign 4
wxml:
    .asciz  "cliptempo"
    .balign 4
gdlyp:
    .byte   {P_BEATSYNC}, {P_PINGPONG}, {P_DLYFILTER}, {P_DLYWIDTH}   /* CC 108-111, as hook C */
    .balign 4
ghcc:
    .byte   {hccs}
    .balign 4
{values}"""
    code, syms = assemble("hookGate", src)       # not "hookG": that is the EQ's
    code = bytearray(code)
    for sym, target, call in (
        ("greg_call", 0x08069e7c, True),
        ("greg_call2", 0x08069e7c, True),
        ("greg_call3", 0x08069e7c, True),
        ("greg_call4", 0x08069e7c, True),
        ("greg_call5", 0x08069e7c, True),
        ("greg_call6", 0x08069e7c, True),
        ("greg_call7", 0x08069e7c, True),
        ("greg_call8", 0x08069e7c, True),
        ("greg_next", reg_next, False),
        ("gstore_orig", 0x0808951e, True),
        ("gstore_call", 0x0808951e, True),
        ("gstore_call2", 0x0808951e, True),
        ("gstore_call3", 0x0808951e, True),
        ("gstore_call4", 0x0808951e, True),
        ("gstore_call5", 0x0808951e, True),
        ("gstore_call6", 0x0808951e, True),
        ("gstore_call7", 0x0808951e, True),
        ("grow_k", clip_kind, True),
        ("grow_c", clip_row, True),
        ("grow_done", CLIP_ROW_DONE, False),
        ("grow_next", CLIP_ROW_SITE + 4, False),
        ("gdpost_call", MIDI_POST_FN, True),
        ("map_setp", SETPARAM_FN, True),
        ("mfinal_keep", row_keep, True),
        ("gsstore_call", 0x0808951e, True),
        ("gsstore_next", nexts["gsstore"], False),
        ("gspost_next", nexts["gspost"], False),
        ("gsedit_next", nexts["gsedit"], False),
        ("gs_set", KEEP_SETPARAM, True),
        ("gcap_out", GATE_IN_CAP_NEXT, False),
        ("gon_call", 0x080aaf78, True),
        ("gon_stock", 0x080aaf78, False),
        ("goff_call", 0x080ab118, True),
        ("goff_stock", 0x080ab118, False),
        ("mon_stock", 0x080a83a4, False),
        ("mon_next", GATE_MIDI_NEXT["mon"], False),
        ("moff_stock", 0x080a83a4, False),
        ("moff_next", GATE_MIDI_NEXT["moff"], False),
        ("gbtn_post", GATE_POST, True),
        ("mcc_next", midi_next, False),
        ("skey_c", sc_key, True),
        ("skey_rms", SC_RMS, False),
        ("mfinal_call", final_next, True),
        ("gcvp_c", cv_pick, True),
        ("grecg_c", rec_gate, True),
        ("mdl_setp", SETPARAM_FN, True),
    ):
        off = syms[sym]
        code[off:off + 4] = enc_b_bl(org + off, target, call)
    struct.pack_into(f"<{len(GATE_IN_VALUES)}I", code, syms["gvalues"],
                     *(org + syms[f"gv{i}"] for i in range(len(GATE_IN_VALUES))))
    struct.pack_into(f"<{len(GATE_RR_VALUES)}I", code, syms["rvalues"],
                     *(org + syms[f"rv{i}"] for i in range(len(GATE_RR_VALUES))))
    struct.pack_into(f"<{len(GATE_ACTION_VALUES)}I", code, syms["dvalues"],
                     *(org + syms[f"dv{i}"] for i in range(len(GATE_ACTION_VALUES))))
    struct.pack_into(f"<{len(GATE_HOLD_VALUES)}I", code, syms["hvalues"],
                     *(org + syms[f"hv{i}"] for i in range(len(GATE_HOLD_VALUES))))
    struct.pack_into(f"<{len(GATE_CV_VALUES)}I", code, syms["cvalues"],
                     *(org + syms[f"cv{i}"] for i in range(len(GATE_CV_VALUES))))
    struct.pack_into(f"<{len(REC_VALUES)}I", code, syms["qvalues"],
                     *(org + syms[f"qv{i}"] for i in range(len(REC_VALUES))))
    struct.pack_into(f"<{len(REC_SEL_VALUES)}I", code, syms["svalues"],
                     *(org + syms[f"sv{i}"] for i in range(len(REC_SEL_VALUES))))
    struct.pack_into(f"<{len(CLIP_ROW_VALUES)}I", code, syms["wvalues"],
                     *(org + syms[f"wv{i}"] for i in range(len(CLIP_ROW_VALUES))))
    return bytes(code), syms


def apply_gate_in(d, n_org, n_syms, hookc_org):
    """Guard Gate In's facts, append it, head the registration chain, wrap both
    pad stores' last AddParam, insert the rows after Excl Group on every pad
    page, retarget the router's param case, its gate calls and its MIDI In
    loops' posts, and give Rec Selected the global store, the Settings posts
    and Settings page 2's second row, after MIDI Rec (b17), the rest one on.
    b21: the Clip Tempo row after Sync on the Clip pages, the Clip voice's
    setter to grow, and hook C's delay post to gdpost."""
    for site, what in GATE_IN_STORE_SITES:
        if branch_target(d, site) != 0x0808951e:
            refuse(f"The {what} store's last parameter is not where Gate In expects it.")
        if bytes(d[site - 4 - BASE:site - BASE]) != bytes.fromhex("bd212046"):
            refuse(f"The {what} store does not end with id 0xbd as Gate In expects.")
    for tab in GATE_IN_TABS:
        ids = list(struct.unpack_from("<45H", d, tab - BASE))
        if 0xa6 not in ids or set(GATE_ROWS) & set(ids) or ids[-len(GATE_ROWS):] != [0] * len(GATE_ROWS):
            refuse(f"The pad page at {tab:#x} is not what Gate In expects.")
    _guard(d, GATE_IN_CAP_SITE - 8, GATE_IN_CAP_STOCK, "router's param case")
    for tab in CLIP_ROW_TABS:
        ids = list(struct.unpack_from("<45H", d, tab - BASE))
        if CLIP_ROW_AFTER not in ids or CLIP_ROW_ID in ids or ids[-1] != 0:
            refuse(f"The Clip page at {tab:#x} is not what the Clip Tempo row expects.")
    _guard(d, CLIP_ROW_SITE, CLIP_ROW_STOCK, "Clip voice's setter, ids above 0xd5,")
    _guard(d, CLIP_ROW_BHI, "00f20281", "Clip voice's setter, its bhi.w to the ids above 0xd5")
    _guard(d, CLIP_ROW_DONE, "04b0bdec028bbde8f081", "Clip voice's setter's epilogue")
    for va, call in STORE_CAP_SITES:
        _guard(d, va, "4021", "store allocation of 64 entries")
        if branch_target(d, call) != 0x0808949e:
            refuse(f"The store allocation at {va:#x} does not call the allocator the Clip Tempo row expects.")
    if branch_target(d, hookc_org + HOOKC_SETP) != SETPARAM_FN:
        refuse("Hook C does not post the delay where the freeze guard expects.")
    if branch_target(d, 0x080ab33c) != GATE_POST:
        refuse("The router's CC fan-out does not post where Gate Action expects.")
    if branch_target(d, 0x080abab6) != GATE_UI_APPEND or struct.unpack_from("<I", d, 0x080abb14 - BASE)[0] != GATE_UI_LIST:
        refuse("The MIDI Rec note does not post where Rec In expects.")
    if bytes(d[0x080abaa8 - BASE:0x080abaaa - BASE]) != bytes.fromhex("2b23"):
        refuse("The MIDI Rec note's event is not 0x2b as Rec In expects.")
    _guard(d, 0x0807c9c4, "48f20103c35c03b1", "the clear's handler returns while a take runs")
    if struct.unpack_from("<8H", d, THEME_ROW_VA - BASE) != (THEME_ID,) + (0,) * 7:
        refuse("Settings page 3 is not Theme alone, as Gate Rec expects.")
    p2 = [r for r in struct.unpack_from("<8H", d, SETTINGS_P2_VA - BASE) if r]
    if not p2 or p2[0] != MIDI_REC_ID or REC_SEL_ID in p2:
        refuse("Settings page 2 does not start with MIDI Rec, as Gate Rec expects.")
    for site, stock, _ in GATE_IN_CALLS:
        if branch_target(d, site) != stock:
            refuse(f"The router's call at {site:#x} is not what Gate In expects.")
    for va, raw, what in (
        (0x080789aa, "47f6c853", "the pad records' base, SessionMgr + 0x7dc8"),
        (0x0807e9e6, "4722", "the Mixer's mute: param 0x47"),
        (0x0807ea0c, "47f6d553ee54", "the Mixer's mute: the record's +0xd"),
        (0x0807079c, f"{SESSION_MGR:08x}", "the UI message handler's object"),
        (0x0807ea14, f"{MANAGER:08x}", "the Mixer's mute posts to the manager"),
    ):
        if va in (0x0807079c, 0x0807ea14):
            ok = struct.unpack_from("<I", d, va - BASE)[0] == int(raw, 16)
        else:
            ok = bytes(d[va - BASE:va - BASE + len(raw) // 2]) == bytes.fromhex(raw)
        if not ok:
            refuse(f"Mute and Solo: {what} is not where they expect it ({va:#x}).")
    if branch_target(d, 0x0807e9ec) != SETPARAM_FN:
        refuse("The Mixer's mute does not post through SetParam as Mute and Solo expect.")
    reg_next = branch_target(d, GATE_IN_REG_SITE)
    midi_next = branch_target(d, MIDI_POST_CALL)
    if branch_target(d, SC_SITE) != SC_RMS:
        refuse(f"The compressor's detector call at {SC_SITE:#x} is not what the sidechain expects.")
    lo, hi = SC_PROLOGUE
    if hashlib.sha256(bytes(d[lo - BASE:hi - BASE])).hexdigest() != SC_PROLOGUE_SHA:
        refuse("The compressor's detector is not the code the sidechain was traced on.")
    if not {"c_sc_key", "c_rec_gate", "c_clip_row", "c_clip_row_keep", "c_clip_kind"} <= set(n_syms):
        refuse("The Character object has no sidechain: --gate-in builds link chr12.")
    final_next = {branch_target(d, site) for site in KEEP_FINAL_SITES}
    if len(final_next) != 1 or min(final_next) < BASE + STOCK_SIZE:
        refuse("The FinalizeBankLoading sites do not lead to one wrapper, as Mute and Solo expect.")
    final_next = final_next.pop()
    nexts = {entry: branch_target(d, site) for site, entry, _ in REC_SEL_SITES}
    org = BASE + len(d)
    code, syms = build_gate_hook(org, reg_next, midi_next, n_org + n_syms["c_sc_key"], final_next,
                                 n_org + n_syms["c_cv_pick"], n_org + n_syms["c_rec_gate"],
                                 n_org + n_syms["c_clip_row"], n_org + n_syms["c_clip_row_keep"], nexts,
                                 n_org + n_syms["c_clip_kind"])
    org2 = _append(d, bytearray(code))
    assert org2 == org
    d[GATE_IN_REG_SITE - BASE:GATE_IN_REG_SITE - BASE + 4] = enc_b_bl(GATE_IN_REG_SITE, org + syms["greg"], True)
    for site, _ in GATE_IN_STORE_SITES:
        d[site - BASE:site - BASE + 4] = enc_b_bl(site, org + syms["gstore"], True)
    for tab in GATE_IN_TABS:
        rows = GATE_ROWS if tab in GATE_CLIP_TABS else GATE_ROWS_ANY   # b25: the Clip-only three on Clip pages
        ids = list(struct.unpack_from("<45H", d, tab - BASE))
        k = ids.index(0xa6) + 1
        ids = ids[:k] + list(rows) + ids[k:len(ids) - len(rows)]   # the last ones are free: checked above
        struct.pack_into("<45H", d, tab - BASE, *ids)
    d[GATE_IN_CAP_SITE - BASE:GATE_IN_CAP_SITE - BASE + 4] = enc_bhi_w(GATE_IN_CAP_SITE, org + syms["gcap"])
    for tab in CLIP_ROW_TABS:
        ids = list(struct.unpack_from("<45H", d, tab - BASE))
        k = ids.index(CLIP_ROW_AFTER) + 1
        struct.pack_into("<45H", d, tab - BASE, *(ids[:k] + [CLIP_ROW_ID] + ids[k:-1]))   # the last is free
    d[CLIP_ROW_SITE - BASE:CLIP_ROW_SITE - BASE + 4] = enc_b_bl(CLIP_ROW_SITE, org + syms["grow"], False)
    for va, _ in STORE_CAP_SITES:
        d[va - BASE:va - BASE + 2] = struct.pack("<H", 0x2100 | STORE_CAP)   # movs r1, #STORE_CAP
    d[hookc_org + HOOKC_SETP - BASE:hookc_org + HOOKC_SETP - BASE + 4] = enc_b_bl(
        hookc_org + HOOKC_SETP, org + syms["gdpost"], True)
    for site, _, entry in GATE_IN_CALLS:
        d[site - BASE:site - BASE + 4] = enc_b_bl(site, org + syms[entry], True)
    d[MIDI_POST_CALL - BASE:MIDI_POST_CALL - BASE + 4] = enc_b_bl(MIDI_POST_CALL, org + syms["mcc"], True)
    d[SC_SITE - BASE:SC_SITE - BASE + 4] = enc_b_bl(SC_SITE, org + syms["skey"], True)
    for site in KEEP_FINAL_SITES:
        d[site - BASE:site - BASE + 4] = enc_b_bl(site, org + syms["mfinal"], True)
    for site, entry, _ in REC_SEL_SITES:
        d[site - BASE:site - BASE + 4] = enc_b_bl(site, org + syms[entry], True)
    rows = p2[:1] + [REC_SEL_ID] + p2[1:]      # one on; what passes slot 7 goes ahead of Theme
    struct.pack_into("<8H", d, SETTINGS_P2_VA - BASE, *rows[:8], *([0] * (8 - len(rows[:8]))))
    p3 = rows[8:] + [THEME_ID]
    struct.pack_into("<8H", d, THEME_ROW_VA - BASE, *p3, *([0] * (8 - len(p3))))
    vprint(f"G Gate In {len(code)} bytes at {org:#010x}, ids {', '.join(f'{i:#x}' for i in GATE_ROWS + (REC_SEL_ID, CLIP_ROW_ID))}, "
           f"ram {GATE_IN_RAM:#x}, {GATE2_RAM:#x}, {REC_RAM:#x}")
    return org, syms


def build_comp_gate_hook(org, hookdr, hookc):
    """Dg: CC 41-45 on channel 1 skip hook Dr while the store says an
    Airwindows type. CC 46 always reaches Dr (b4): auto makeup is shared by
    every type, so Stock's must follow it from any type. Reached by F's tail branch with the post's frame at sp
    (as Dr is); r0/r1 are the thunk's arguments, r3 and r12 are scratch."""
    src = f"""
    .syntax unified
    .thumb
    .section .text
    .global _sDg
    .thumb_func
_sDg:
    ldr     r12, [sp, #{MSG_CHAN_SP:#x}]
    cmp     r12, #{COMP_CHANNEL}
    bne     dg_dr
    ldr     r12, [sp, #{MSG_CC_SP:#x}]
    sub     r12, r12, #{CC_COMP_FIRST}
    cmp     r12, #4
    bhi     dg_dr
    ldr     r12, =0x{CMP_STORE_RUN:08x}
    ldr     r12, [r12]
    ldr     r3, =0x{CMP_RUN:08x}
    cmp     r12, r3
    beq     dg_skip
dg_dr:
    .short  0, 0                    /* b.w hook Dr */
dg_skip:
    .short  0, 0                    /* b.w hook C, Dr's own next */
    .balign 4
    .ltorg
"""
    code, syms = assemble("hookDg", src)
    code = bytearray(code)
    for sym, target in (("dg_dr", hookdr), ("dg_skip", hookc)):
        off = syms[sym]
        code[off:off + 4] = enc_b_bl(org + off, target, False)
    return bytes(code)


def build_comp_type_hook(org, nexts, post_fn):
    src = f"""
.syntax unified
.thumb
.section .text
.global _sQ
.thumb_func
_sQ:
qreg:                               /* r0 = registry; as P's preg */
    push    {{r0, r1, r2, r3, r4, r12, lr}}
    sub     sp, #12
    movw    r1, #0x{CMP_ID:x}
    adr.w   r2, qlabel
    adr.w   r3, qvalues
    movs    r4, #{len(CMP_VALUES)}
    str     r4, [sp]
    adr.w   r4, qxml
    str     r4, [sp, #4]
qreg_call:
    .short  0, 0                    /* enum registrar */
    add     sp, #12
    pop     {{r0, r1, r2, r3, r4, r12, lr}}
qreg_next:
    .short  0, 0

qstore:                             /* r0 = the global store */
    push    {{r0, r1, r2, r3, r12, lr}}
    movw    r1, #0x{CMP_ID:x}
    movs    r2, #0                  /* default Stock */
qstore_call:
    .short  0, 0                    /* AddParam */
    pop     {{r0, r1, r2, r3, r12, lr}}
qstore_next:
    .short  0, 0

qpost:                              /* PostSetParam(r0 mgr, r1 key, r2 id, r3 value) */
    movw    r12, #0x{CMP_ID:x}
    cmp     r2, r12
    bne     qpost_next
    push    {{r0, r1, r2, r3, r12, lr}}   /* ours: to the C, NOT to the engine */
    mrs     r1, apsr
    vmrs    r2, fpscr
    push    {{r1, r2}}
    vpush   {{s0-s15}}
    mov     r0, r3
qpost_call:
    .short  0, 0                    /* bl cmp_post(value) */
    vpop    {{s0-s15}}
    pop     {{r1, r2}}
    msr     apsr_nzcvq, r1
    vmsr    fpscr, r2
    pop     {{r0, r1, r2, r3, r12, pc}}
qpost_next:
    .short  0, 0
    .balign 4
qvalues:
    .word   {", ".join("0" for _ in CMP_VALUES)}       /* -> the value names */
    .balign 4
qlabel:
    .asciz  "Comp Type:"
    .balign 4
qxml:
    .asciz  "comptype"
    .balign 4
{"".join(f'''qv{i}:
    .asciz  "{v}"
    .balign 4
''' for i, v in enumerate(CMP_VALUES))}"""
    code, syms = assemble("hookQ", src)
    code = bytearray(code)
    for sym, target, call in (
        ("qreg_call", 0x08069e7c, True),
        ("qreg_next", nexts["qreg"], False),
        ("qstore_call", 0x0808951e, True),
        ("qstore_next", nexts["qstore"], False),
        ("qpost_call", post_fn, True),
        ("qpost_next", nexts["qpost"], False),
    ):
        off = syms[sym]
        code[off:off + 4] = enc_b_bl(org + off, target, call)
    struct.pack_into(f"<{len(CMP_VALUES)}I", code, syms["qvalues"],
                     *(org + syms[f"qv{i}"] for i in range(len(CMP_VALUES))))
    return bytes(code), syms


# --- Clip Tempo (2.3.10, --comp-types): Vinyl on a Clip pad -------------------------
# CC 112 on a pad's own channel steps that Clip pad Off <-> Vinyl: its read rate
# times F x BPM / (T x 3000 x sr), so the loop is the right length for the bar and
# Clip Sync stops jumping (character/clip_tempo.h has the maths;
# CLIP-STRETCH-FEASIBILITY.md section 1.5 the stock timing). Three sites, all
# shims in hook N's 2.3.10 variant (N is built with the C, so it knows its
# addresses), installed here because two of them depend on hooks B and P:
#   - the pitch factor: `vldr s16, [r4, #0x18]` at 0x080b57f6 in the segment
#     renderer, straight after the exp2 lookup (bl at 0x080b57f2) and before it is
#     copied to s17 and multiplied into both rate paths (0x080b580a, 0x080b5868,
#     0x080b59e4), the last slice's hold recompute included. LR is free there (the
#     function pushed it), the flags are dead (the next orrs sets them).
#   - CC 112: hook B's exit when no arm matched (fB, `b.w 0x080b7554`, the voice's
#     event loop); r3 still holds the CC number (0x080b7cc4 ldrb r3, [sp, #0x34]),
#     the value is at [sp, #0x38], r4 the voice and r9 the clock (hook B notes).
#   - preset loads: both FinalizeBankLoading sites, which hook P has already
#     wrapped (pfinal); nfinal calls pfinal, then clip_loaded clears the modes
#     unless Keep CCs is ON.
# b8 adds Manual (CC 113: the pad follows Preset BPM, free of the clock's grid),
# CC 114 (Preset BPM 1-255 in steps of 2), and:
#   - the Beat Count read: `ldr.w r3, [sl, #0xb80]` at 0x080b42ac in the clip
#     timing 0x080b40fc (sl = the voice, fp = the clock). Both its paths use r3
#     (cbz-like test at 0x080b42b2, the beat count at 0x080b44a2), so nclip_beats
#     returns the count in r3 and leaves every other register as it was. In
#     Vinyl and Manual it is a count made once at Preset BPM, so stock's Auto
#     guess at the CURRENT tempo cannot halve or double the loop.
#   - Preset BPM's range: the registration's min and max (0x0806a8b6, 0x0806a8b2)
#     become 1 and 255, and hook L's HOLD capture clamps to the same.
CLIP_CC = 112
CLIP_CC_MANUAL = 113
CLIP_CC_BPM = 114
CLIP_CC_FIRST = 102                  # clip_tempo.h: CLIP_CC_FIRST, CLIP_CC_LAST: 102 Brake (b36), 104 Freeze,
CLIP_CC_LAST = 119                   # 105 Pull Up (b14), 107 Power Down (b36), 112-116 Clip Tempo, 117 Jungle
CLIP_CC_SCRATCH = 78                 # Mode, 118 Roll, 119 Pitch Roll; and 78, Baby Scratch (b36), let in alone
CLIP_READ_SITE = 0x080b58fc          # bl 0x080b55ac: the segment renderer's read (Jungle)
JGL_RAM = (0x2406a200, 0x2406ef00)   # clip_tempo.h: CLIP_JGL_ADDR0/1, slot 0 and 1 of every pad
JGL_BYTES = 16 * 24                  # clip_tempo.h: CLIP_JGL_BYTES, each
CLIP_MISS_RAM = 0x2406a640           # clip_tempo.h: CLIP_MISS_ADDR, a read that found no block (b19)
CLIP_MAN_RAM = 0x2406a6b0            # clip_tempo.h: CLIP_MAN_RAM, each pad's Manual tempo (b27, 16 floats)
CLIP_ELAST_RAM = 0x2406c100          # clip_tempo.h: CLIP_ELAST_RAM, a held button's last e (b28, 16 x 4 floats)
STRM_VT_READ = 0x080ca600            # the streamer's vtable +4 (b22: its WRITE, 0x0809a008; the read is +8)
CLIP_DV_RAM = 0x2406a380             # clip_tempo.h: CLIP_DV_ADDR, where each segment reads (Jungle Modes)
CLIP_DV_BYTES = 2 * 16 * 4
assert JGL_RAM[0] + JGL_BYTES <= CLIP_DV_RAM and CLIP_DV_RAM + CLIP_DV_BYTES <= KEEP_RAM
CLIP_BPM_RANGE = (1, 255)            # Preset BPM's Settings row (b21)
CLIP_RAM = 0x2406bb00                # character/clip_tempo.h: CLIP_RAM_ADDR
CLIP_RAM_BYTES = 0x500               # clip_tempo.h: CLIP_RAM_BYTES (b13: the Jungle Modes' state)
assert CLIP_RAM >= CMP_RAM + CMP_RAM_BYTES and CLIP_RAM + CLIP_RAM_BYTES <= PATCH_RAM
CLIP_RATE_SITE = 0x080b57f6
CLIP_BEATS_SITE = 0x080b42ac
CLIP_CC_RET = 0x080b7554             # hook B's return: the voice's event loop
CLIP_BPM_REG = ((0x0806a8b6, 0x28), (0x0806a8b2, 0xfa))   # movs r3, #40 / #250: BPM:'s min, max
CLIP_EXTERNS = {                     # stock functions clip_tempo.h calls as their callers do
    "clip_x_timing": 0x080b40fc | 1,   # (voice, clock): the clip timing, as the setter calls it
    "clip_x_len": 0x080a45ac | 1,      # (sample) -> frames
    "clip_x_start": 0x080b490c | 1,    # (voice, note, delay, slice, clock, note number, 0) -> segment
    "clip_x_getparam": 0x080894d0 | 1,  # GetParam(store, id); L may sit on its entry
    "clip_x_read": 0x080b55ac | 1,     # (rate; voice, -, pos, -, n, &adv, &frac, src, dst, &out)
    "clip_x_alloc": 0x08042dc0 | 1,    # (bytes) -> SDRAM, 16-aligned; past its limit it halts the module
    "clip_x_sread": 0x0809a008 | 1,    # the streamer's read (its vtable +8): 0 when the block is not cached
}
CLIP_GUARDS = (                      # (va, bytes, what): the facts the shims rest on
    (0x080b42ac, "daf8803b", "ldr.w r3, [sl, #0xb80], the clip timing's Beat Count read"),
    (0x080b58f8, "d4e90223fff756fe8146", "ldrd r2, r3, [r4, #8]; bl 0x080b55ac; mov sb, r0: the read"),
    (0x080b55ac, "f0b50446406a1546", "the read's entry"),
    (0x080b42b2, "002b40f0f580", "cmp r3, #0; bne.w: Auto or the count"),
    (0x080b44a2, "07ee903a", "vmov s15, r3: the count, used as read"),
    (0x080b40fc, "2de9f04f8246006a", "the clip timing's entry: push; mov sl, r0; ldr r0, [r0, #0x20]"),
    (0x080b490c, "2de9f04f1d46", "the segment start's entry"),
    (0x080a45ac, "016a79b1", "the sample's frame count"),
    (0x080937f4, "2de9f04387b0", "PostSetParam's entry"),
    (0x080b748a, "012385f82930", "the setter: +0x29 = 1 for a Clip or Slicer pad"),
    (0x0806a8b0, "0293fa2301932823", "BPM:'s registration: max 250, min 40"),
    (0x080b57f2, "e9f733fe", "bl 0x0809f45c, the pitch factor's exp2"),
    (0x080b57f6, "94ed068a", "vldr s16, [r4, #0x18], the segment's base rate"),
    (0x080b57fa, "f0ee408a", "vmov.f32 s17, s0, the factor kept for the second path"),
    (0x080b7cc4, "9df83430", "ldrb r3, [sp, #0x34], the CC number hook B dispatches on"),
)
assert KEEP_RAM == 0x2406a400 and KEEP_ON == 0x4b454550   # clip_tempo.h: CLIP_KEEP_RAM, CLIP_KEEP_ON


def cond_branch_target(d, at):
    """Target of the 32-bit conditional branch (T3) at `at`."""
    hw1, hw2 = struct.unpack_from("<HH", d, at - BASE)
    if hw1 & 0xf800 != 0xf000 or hw2 & 0xd000 != 0x8000 or (hw1 >> 6) & 0xf >= 0xe:
        refuse(f"No conditional branch at {at:#x} where the patcher expects one.")
    s, imm6 = (hw1 >> 10) & 1, hw1 & 0x3f
    j1, j2, imm11 = (hw2 >> 13) & 1, (hw2 >> 11) & 1, hw2 & 0x7ff
    off = (s << 20) | (j2 << 19) | (j1 << 18) | (imm6 << 12) | (imm11 << 1)
    if s:
        off -= 1 << 21
    return at + 4 + off


def apply_clip_tempo(d, n_org, n_syms):
    """Install Clip Tempo's three sites (after hooks B, N and P)."""
    for va, raw, what in CLIP_GUARDS:
        _guard(d, va, raw, what)
    # 1. the pitch factor
    d[CLIP_RATE_SITE - BASE:CLIP_RATE_SITE - BASE + 4] = enc_b_bl(
        CLIP_RATE_SITE, n_org + n_syms["nclip_rate"], True)
    # 2. CC 112: hook B's no-match exit
    # The site's bne.w leads to O's pad recorder, which chains on to B, so B is
    # found by its own dispatch: its leading compares and in-blob branches are
    # the same bytes wherever it lands. Exactly one copy, after the stock image.
    b_blob, b_syms = FROZEN["hookB"]
    head = bytes.fromhex(b_blob)[:b_syms["fB"]]
    hits = [i for i in range(STOCK_SIZE, len(d) - len(head)) if d[i:i + len(head)] == head]
    if len(hits) != 1:
        refuse("Hook B is not installed where Clip Tempo expects it.")
    b_org = BASE + hits[0]
    if cond_branch_target(d, HOOKS[1][1]) < BASE + STOCK_SIZE:     # bne.w: type 1 still reaches stock
        refuse("The Clip/Slicer CC site is not hooked.")
    fb = b_org + b_syms["fB"] - b_syms["_sB"]
    if bytes(d[fb - BASE:fb - BASE + 4]) != enc_b_bl(fb, CLIP_CC_RET, False):
        refuse("Hook B's exit is not the branch Clip Tempo expects.")
    d[fb - BASE:fb - BASE + 4] = enc_b_bl(fb, n_org + n_syms["nclip_cc"], False)
    # 3. preset loads: both FinalizeBankLoading sites, already wrapped by P
    pfinal = {branch_target(d, site) for site in KEEP_FINAL_SITES}
    if len(pfinal) != 1 or min(pfinal) < BASE + STOCK_SIZE:
        refuse("The FinalizeBankLoading sites do not lead to Keep CCs' wrapper.")
    pfinal = pfinal.pop()
    if bytes(d[pfinal - BASE:pfinal - BASE + 2]) != bytes.fromhex("10b5"):   # push {r4, lr}
        refuse("Keep CCs' wrapper does not begin as Clip Tempo expects.")
    p = n_org + n_syms["nfinal_p"]
    if bytes(d[p - BASE:p - BASE + 4]) != b"\0\0\0\0":
        refuse("Clip Tempo's load shim is not where the patcher expects it.")
    d[p - BASE:p - BASE + 4] = enc_b_bl(p, pfinal, True)
    for site in KEEP_FINAL_SITES:
        d[site - BASE:site - BASE + 4] = enc_b_bl(site, n_org + n_syms["nfinal"], True)
    # 4b. the segment renderer's read: Jungle's two playheads
    d[CLIP_READ_SITE - BASE:CLIP_READ_SITE - BASE + 4] = enc_b_bl(
        CLIP_READ_SITE, n_org + n_syms["njread"], True)
    # 4. the clip timing's Beat Count read
    d[CLIP_BEATS_SITE - BASE:CLIP_BEATS_SITE - BASE + 4] = enc_b_bl(
        CLIP_BEATS_SITE, n_org + n_syms["nclip_beats"], True)
    # 4c. the streamer's read, through its vtable (only ever called through it:
    # no direct call to 0x0809a008 anywhere in the image): a miss is flagged,
    # and the modes' reads play silence instead of the stale fetch buffer (b19)
    if struct.unpack_from("<I", d, STRM_VT_READ - BASE)[0] != 0x0809a008 | 1:
        refuse("The streamer's vtable read entry is not what Clip Tempo expects.")
    struct.pack_into("<I", d, STRM_VT_READ - BASE, (n_org + n_syms["c_clip_sread"]) | 1)

    # 5. Preset BPM's range, at the registration (movs r3, #imm8) and in hook L's
    # HOLD capture (cmp/it/mov r5 pairs), which clamps a held tempo to it, so L
    # must be installed.
    lo, hi = CLIP_BPM_RANGE
    for (va, old), new in zip(CLIP_BPM_REG, (lo, hi)):
        if bytes(d[va - BASE:va - BASE + 2]) != bytes((old, 0x23)):
            refuse(f"Preset BPM's registration at {va:#x} is not what Clip Tempo expects.")
        d[va - BASE] = new
    clamp = bytes.fromhex("282d38bf2825fa2d88bffa25")   # cmp r5,#40; it lo; movlo r5,#40; ... #250
    hits = [i for i in range(STOCK_SIZE, len(d) - len(clamp)) if d[i:i + len(clamp)] == clamp]
    if len(hits) != 1:
        refuse("Hook L's HOLD capture clamp is not where Clip Tempo expects it (needs --preset-bpm).")
    i = hits[0]
    d[i:i + len(clamp)] = bytes((lo, 0x2d, 0x38, 0xbf, lo, 0x25, hi, 0x2d, 0x88, 0xbf, hi, 0x25))


def apply_comp_type(d, n_org, n_syms):
    """Guard Q's facts, append Q, take each site at the head of its chain."""
    _guard(d, CLK_REG_LIMIT_VA, CLK_REG_LIMIT, "parameter registry limit")
    _guard(d, CLK_STORE_CAP_VA, CLK_STORE_CAP, "global settings capacity")
    for va, target in CMP_CALLS:
        if branch_target(d, va) != target:
            refuse(f"The call at {va:#x} is not what the compressor types expect.")
    nexts = {entry: branch_target(d, site) for site, entry, _ in COMP_SITES}
    org = BASE + len(d)
    code, syms = build_comp_type_hook(org, nexts, n_org + n_syms["c_cmp_post"])
    org2 = _append(d, bytearray(code))
    assert org2 == org
    for site, entry, _ in COMP_SITES:
        d[site - BASE:site - BASE + 4] = enc_b_bl(site, org + syms[entry], True)
    vprint(f"Q compressor types {len(code)} bytes at {org:#010x}, id {CMP_ID:#x}, ram {CMP_RAM:#x}")
    return org, syms


# --- U: the SD card recovery (2.3.11-mod, GitHub issue #6) ------------------------
# 2.3.10-mod restarted during Brightness, Theme and preset saves, then looped
# at boot until the card lost power. The restart is WWDG1's: the audio block
# refreshes it only while the file thread's heartbeat is under 0xea5 blocks
# (~10 s) old. Every wait that outran it was in 1010's SD code:
#   - HAL_SD_InitCard (0x0804d264) asks "are you ready?" (CMD55, ACMD41) up to
#     65,535 times at the 393 kHz start-up clock (ClockDiv 0xfa), at least
#     35 s. dg7's and dg8's stalls were this loop: pc 0x0804c6f0 is CMD55's
#     response wait, 0x0804d329 its return inside the loop, 0x080406c7
#     BSP_SD_Init's.
#   - Any CMD8 error (0x0804d2e2) is taken for a pre-2006 card: CMD0 again,
#     then ACMD41 with no CMD8, which a high-capacity card may answer busy for
#     good (the SD spec: HCS is ignored by a card that didn't accept CMD8).
#   - HAL_SD_ErrorCallback (0x080431dc) only prints, to an empty stub, so a
#     data error leaves SD_read or SD_write its whole 5 s message wait.
#   - HAL_SD_Init's last wait never gives up (it compares the time taken
#     with -1).
# A watchdog restart leaves the card powered (MspInit 0x08043028 sets up CK,
# CMD and D0-D3 only: no power or detect pin), so a card stuck in its
# start-up stays stuck and every boot stalls in the same place.
#
# The rule (owner, 2026-11-04): every card wait stays AT LEAST as patient as
# stock, so no card that works on stock can fail on this. Stock's real limit
# was the watchdog's ~10 s; U keeps the watchdog fed while the card is
# answering, and when a wait runs out the start-up fails (stock then shows
# "Please insert microSD card") instead of the module restarting:
#   - ACMD41: stock's 65,535 tries, and SD_START_MS (10 s) on the clock from
#     the first try; each answered CMD55 stamps the file thread's heartbeat;
#   - CMD8: asked again after a CMD0, up to three times, before stock's v1 path;
#   - CMD0: only once the card has let go of DAT0 (busy), or after 500 ms;
#   - the ready waits (stock's 5 s) and HAL_SD_Init's last wait (8.2 s, under
#     the watchdog even if the card falls silent) stamp the heartbeat on each
#     answered CMD13;
#   - a data error (DCRCFAIL, DTIMEOUT, TXUNDERR, RXOVERR: ErrorCode & 0x3a)
#     posts 3 to the SD queue, which SD_read and SD_write take as a failure
#     at once (stock failed it too, after 5 s). A failed CMD12 alone after a
#     good transfer posts nothing: the completion follows it, and stock counts
#     that a success;
#   - before each transfer the queue is emptied, so a late message from a
#     transfer that outlived its wait cannot end the next one early.
# The heartbeat is stamped only after an answer: a card gone silent, or the
# SD hardware locked, still meets the watchdog as on stock. All of it runs on
# the file thread (FatFs's disk_initialize, SD_read, SD_write), as the stamp
# it makes (0x08044f90) always has.
SD_VERSION = "2.3.11-mod"            # --v2311: the published 2.3.11-mod (the default output in 2.3.11)
V2311_SHA = "f5fa62b3fe5e18a2a941e200a054230fef9fd32834d342b379d8702ca0ec109b"   # --v2311: 2.3.11-mod
V2310_SHA = "62f15b366fdac8181ca070b5ddf53476955c91ca80e184d526782cf8d49ac7b7"   # --v2310: 2.3.10-mod
SD_START_MS = 10000                  # ACMD41: stock's effective limit, the watchdog's ~10 s
SD_CMD8_TRIES = 3
SD_FREE_MS = 500
SD_GAP_MS = 2                        # HAL_Delay after a failed CMD8, and after the CMD0 that follows it
SD_INIT_WAIT_MS = 8192               # HAL_SD_Init's last wait (stock: none): under the watchdog if silent
SD_ERR_MSG = 3                       # SD_read takes 1 as done, SD_write 2; anything else is a failure
SD_DATA_ERRORS = 0x3a                # hsd->ErrorCode: DCRCFAIL, DTIMEOUT, TXUNDERR, RXOVERR
SD_TIMEOUT = 0x80000000              # SDMMC_ERROR_TIMEOUT, the loop's way out
SD_QUEUE = 0x24009cb8                # the SD queue's handle: SD_read's, SD_write's, the callbacks'
SD_HSD = 0x24003044                  # the SD handle
SD_HB = 0x24009cac                   # the heartbeats: +0 the file thread, +8 the audio block count
SD_DAT0_IDR = 0x58020810             # GPIOC IDR: PC8 is SDMMC1_D0 (MspInit's AF12 pins 8-11)
SD_RAM = 0x2406a628                  # +0 the first try's tick, +4 tries, +8 ms, +12 starts so far
SD_RAM_BYTES = 16
SD_DRAIN_MAX = 16
SD_CALLS = (                         # (site, stock target, entry): the BLs U takes over
    (0x0804d2ba, 0x0804ca6c, "sd_cmd0"),     # HAL_SD_InitCard's CMD0
    (0x0804d2de, 0x0804cac8, "sd_cmd8"),     # its CMD8
    (0x0804d2fe, 0x0804ca6c, "sd_cmd0"),     # the v1 path's CMD0
    (0x0804d324, 0x0804cb60, "sd_app"),      # the ACMD41 loop's CMD55
    (0x0804d884, 0x0804d7e4, "sd_state"),    # HAL_SD_Init's last wait: HAL_SD_GetCardState
    (0x08045038, 0x08040720, "sd_ready"),    # the ready wait before a read or write: BSP_SD_GetCardState
    (0x080450a4, 0x08040720, "sd_ready"),    # SD_read's ready wait after
    (0x08045116, 0x08040720, "sd_ready"),    # SD_write's ready wait after
    (0x080431e2, 0x08042db8, "sd_err"),      # HAL_SD_ErrorCallback's print, r1 = ErrorCode
    (0x08045066, 0x080406e8, "sd_rd"),       # SD_read's BSP_SD_ReadBlocks_DMA
    (0x080450d8, 0x08040704, "sd_wr"),       # SD_write's BSP_SD_WriteBlocks_DMA
)
SD_IMMEDIATES = (                    # (va, stock bytes, new bytes, what)
    (0x0804d892, "b0f1ff3f", "b0f5005f", "HAL_SD_Init's last wait, cmp.w r0, #-1 -> #8192"),
    (0x0804d896, "f4d1", "f4d3", "HAL_SD_Init's last wait, bne -> bcc: give up at 8.2 s"),
)
SD_FNS = {                           # the stock functions U calls ...
    "cmd0": 0x0804ca6c,              # SDMMC_CmdGoIdleState
    "cmd8": 0x0804cac8,              # SDMMC_CmdOperCond
    "cmd55": 0x0804cb60,             # SDMMC_CmdAppCommand
    "state": 0x0804d7e4,             # HAL_SD_GetCardState: 0 when CMD13 got no answer
    "get_tick": 0x08054a24,          # HAL_GetTick
    "delay": 0x08054a30,             # HAL_Delay
    "msg_put": 0x08059a48,           # osMessagePut
    "msg_get": 0x08059aa4,           # osMessageGet(&event, queue, ms)
    "rd_dma": 0x080406e8,            # BSP_SD_ReadBlocks_DMA
    "wr_dma": 0x08040704,            # BSP_SD_WriteBlocks_DMA
}
SD_PROOFS = (                        # ... each proved by a stock call of it (the rest by SD_CALLS)
    (0x0804d2b0, SD_FNS["delay"]),   # HAL_SD_InitCard's HAL_Delay
    (0x0804d87c, SD_FNS["get_tick"]),    # HAL_SD_Init's HAL_GetTick
    (0x080451b6, SD_FNS["msg_put"]),     # BSP_SD_WriteCpltCallback's osMessagePut
    (0x0804507a, SD_FNS["msg_get"]),     # SD_read's osMessageGet
    (0x08040724, SD_FNS["state"]),       # BSP_SD_GetCardState's HAL_SD_GetCardState
)
SD_GUARDS = (                        # (va, bytes, what): the facts U rests on
    (0x0804d274, "fa23", "the start-up clock, ClockDiv 0xfa (393 kHz)"),
    (0x0804d30e, "039a4ff6fe739a4200f2b28000255e4f1e4629462068fff71cfc03460028c9d139462068fff72efc"
                 "002840f09b8029462068fff7bafa039b01330393039b0246002801dbb342e4d90399",
     "the ACMD41 loop: the try count at [sp, #0xc], CMD55 then ACMD41, out when ready or on an error"),
    (0x0804d2c2, "012584f83050626b13436363", "the loop's error way out: ErrorCode |= the result"),
    (0x080431dc, "08b5416b0148", "HAL_SD_ErrorCallback: r1 = ErrorCode at its print"),
    (0x0804da00, "5a6b12f03a0f", "the SD interrupt's data errors, STA & 0x3a"),
    (0x0804507e, "019b102b01d0012015e0029b012b01d0012010e0", "SD_read: a message, and 1, or it fails"),
    (0x080450f0, "019b102b01d0012015e0029b022b01d0012010e0", "SD_write: a message, and 2, or it fails"),
    (0x080450b8, "b89c0024", "SD_read's queue handle, 0x24009cb8"),
    (0x0804512c, "b89c0024", "SD_write's queue handle, 0x24009cb8"),
    (0x080451ac, "08b500220221024b186814f047fc08bd", "BSP_SD_WriteCpltCallback, posting 2"),
    (0x080451c0, "08b500220121024b186814f03dfc08bd", "BSP_SD_ReadCpltCallback, posting 1"),
    (0x08040720, "08b503480df05ef8043818bf012008bd44300024",
     "BSP_SD_GetCardState: HAL_SD_GetCardState(hsd) == 4 (TRANSFER) gives 0, else 1"),
    (0x0804d7f4, "636b034363630020c0f34320", "HAL_SD_GetCardState: no answer gives 0"),
    (0x08044f90, "836803607047", "the file thread's heartbeat: +0 = +8"),
    (0x0804305c, "4ff47063", "MspInit's data pins, 8-11 (D0 is pin 8)"),
    (0x08043198, "00080258", "MspInit's data pins' port, GPIOC 0x58020800"),
    (0x08054a24, "014b18687047", "HAL_GetTick"),
)


def build_sd_hook(org):
    """U: the card's start-up, error and transfer paths, as patient as stock.

    sd_cmd0, sd_cmd8, sd_app and sd_state stand in for HAL_SD_InitCard's and
    HAL_SD_Init's calls (r0 = the SDMMC or the handle; r4-r6 kept, as the
    callees keep them). sd_ready stands in for BSP_SD_GetCardState. sd_err
    stands in for the error callback's print (r0 the format, r1 ErrorCode).
    sd_rd and sd_wr stand in for the DMA starts (r0-r2 their arguments).
    sd_beat is the file thread's heartbeat, as 0x08044f90 stamps it.
    """
    src = f"""
.syntax unified
.thumb
.section .text
.global _sU
.thumb_func
_sU:
sd_cmd8:                            /* r0 = the SDMMC: CMD8, and after a failure CMD0 and CMD8 again */
    push    {{r4, r5, r6, lr}}
    mov     r4, r0
    movs    r5, #{SD_CMD8_TRIES}
sd_cmd8_try:
    mov     r0, r4
sd_cmd8_call:
    .short  0, 0
    cbz     r0, sd_cmd8_out         /* answered: a v2 card */
    subs    r5, #1
    beq     sd_cmd8_out             /* out of tries: stock's v1 path takes it from here */
    movs    r0, #{SD_GAP_MS}
sd_cmd8_gap1:
    .short  0, 0
    mov     r0, r4
    bl      sd_cmd0
    cbnz    r0, sd_cmd8_out         /* CMD0 itself failed: give up with its error */
    movs    r0, #{SD_GAP_MS}
sd_cmd8_gap2:
    .short  0, 0
    b       sd_cmd8_try
sd_cmd8_out:
    pop     {{r4, r5, r6, pc}}
sd_cmd0:                            /* r0 = the SDMMC: CMD0 once the card lets go of DAT0 */
    push    {{r4, r5, r6, lr}}
    mov     r4, r0
sd_cmd0_t0:
    .short  0, 0
    mov     r5, r0
sd_cmd0_poll:
    ldr     r3, =0x{SD_DAT0_IDR:08x}
    ldr     r3, [r3]
    tst     r3, #0x100              /* PC8, SDMMC1_D0: high, not busy */
    bne     sd_cmd0_go
sd_cmd0_t1:
    .short  0, 0
    subs    r0, r0, r5
    cmp.w   r0, #{SD_FREE_MS}
    bcc     sd_cmd0_poll
sd_cmd0_go:
    mov     r0, r4
    pop     {{r4, r5, r6, lr}}
sd_cmd0_next:
    .short  0, 0
sd_app:                             /* the ACMD41 loop's CMD55: r0 = the SDMMC, r1 = 0 */
    ldr     r2, [sp, #0xc]          /* HAL_SD_InitCard's try count, before this try */
    push    {{r4, r5, r6, lr}}
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
sd_app_t:
    .short  0, 0
    ldr     r3, =0x{SD_RAM:08x}
    cbnz    r6, sd_app_on
    str     r0, [r3]                /* the first try: when the asking began, and one more start */
    ldr     r1, [r3, #12]
    adds    r1, #1
    str     r1, [r3, #12]
sd_app_on:
    ldr     r2, [r3]
    subs    r2, r0, r2              /* ms since the first try */
    adds    r1, r6, #1
    str     r1, [r3, #4]            /* tries, this one too */
    str     r2, [r3, #8]
    movw    r1, #{SD_START_MS}
    cmp     r2, r1
    bcs     sd_app_late
    mov     r0, r4
    mov     r1, r5
sd_app_call:
    .short  0, 0
    cbnz    r0, sd_app_out          /* no answer: the loop gives up, as on stock */
    bl      sd_beat                 /* the card answered: the file thread is alive */
    movs    r0, #0
sd_app_out:
    pop     {{r4, r5, r6, pc}}
sd_app_late:
    mov.w   r0, #0x{SD_TIMEOUT:08x}             /* the loop's error way out: the start-up fails */
    pop     {{r4, r5, r6, pc}}
sd_state:                           /* HAL_SD_Init's last wait: r0 = the handle */
    push    {{r4, lr}}
sd_state_call:
    .short  0, 0
    mov     r4, r0
    cbz     r0, sd_state_out        /* no answer */
    bl      sd_beat
sd_state_out:
    mov     r0, r4
    pop     {{r4, pc}}
sd_ready:                           /* BSP_SD_GetCardState, the ready waits' */
    push    {{r4, lr}}
    ldr     r0, =0x{SD_HSD:08x}
sd_ready_call:
    .short  0, 0
    mov     r4, r0
    cbz     r0, sd_ready_out        /* no answer */
    bl      sd_beat
sd_ready_out:
    subs    r0, r4, #4              /* TRANSFER gives 0, anything else 1 */
    it      ne
    movne   r0, #1
    pop     {{r4, pc}}
sd_beat:                            /* the file thread's heartbeat, as 0x08044f90 stamps it */
    ldr     r3, =0x{SD_HB:08x}
    ldr     r2, [r3, #8]
    str     r2, [r3]
    bx      lr
sd_err:                             /* the error callback's print: r1 = hsd->ErrorCode */
    tst.w   r1, #0x{SD_DATA_ERRORS:x}               /* a data error, not a stop command's */
    beq     sd_err_out
    ldr     r3, =0x{SD_QUEUE:08x}
    ldr     r0, [r3]
    cbz     r0, sd_err_out
    movs    r1, #{SD_ERR_MSG}
    movs    r2, #0
sd_err_put:
    .short  0, 0
sd_err_out:
    bx      lr
sd_rd:                              /* SD_read's DMA start: a stale message first goes */
    push    {{r0, r1, r2, lr}}
    bl      sd_drain
    pop     {{r0, r1, r2, lr}}
sd_rd_next:
    .short  0, 0
sd_wr:                              /* SD_write's DMA start: the same */
    push    {{r0, r1, r2, lr}}
    bl      sd_drain
    pop     {{r0, r1, r2, lr}}
sd_wr_next:
    .short  0, 0
sd_drain:                           /* take what waits on the SD queue, at most SD_DRAIN_MAX */
    push    {{r4, lr}}
    sub     sp, #16                 /* the osEvent: status, value, def */
    movs    r4, #{SD_DRAIN_MAX}
sd_drain_next:
    ldr     r3, =0x{SD_QUEUE:08x}
    ldr     r1, [r3]
    cbz     r1, sd_drain_out
    mov     r0, sp
    movs    r2, #0                  /* no wait */
sd_drain_get:
    .short  0, 0
    ldr     r3, [sp]
    cmp     r3, #0x10               /* osEventMessage: one was waiting */
    bne     sd_drain_out
    subs    r4, #1
    bne     sd_drain_next
sd_drain_out:
    add     sp, #16
    pop     {{r4, pc}}
    .balign 4
    .ltorg
"""
    code, syms = assemble("hookSD", src)
    code = bytearray(code)
    for sym, fn, call in (
        ("sd_cmd8_call", "cmd8", True),
        ("sd_cmd8_gap1", "delay", True),
        ("sd_cmd8_gap2", "delay", True),
        ("sd_cmd0_t0", "get_tick", True),
        ("sd_cmd0_t1", "get_tick", True),
        ("sd_cmd0_next", "cmd0", False),
        ("sd_app_t", "get_tick", True),
        ("sd_app_call", "cmd55", True),
        ("sd_state_call", "state", True),
        ("sd_ready_call", "state", True),
        ("sd_err_put", "msg_put", False),
        ("sd_rd_next", "rd_dma", False),
        ("sd_wr_next", "wr_dma", False),
        ("sd_drain_get", "msg_get", True),
    ):
        off = syms[sym]
        assert code[off:off + 4] == b"\0\0\0\0", sym
        code[off:off + 4] = enc_b_bl(org + off, SD_FNS[fn], call)
    return bytes(code), syms


# U's second half, the cause (character/sdwake.c, measured 2026-11-07): a card
# that sleeps after 20-30 s idle and takes up to 8.35 s to answer its next read,
# against stock's 5 s wait. A keep-alive read at the file thread's idle point,
# a 9 s wait for the transfer, and a stuck transfer stopped and tried once more.
SDK_SRC = os.path.join(os.path.dirname(os.path.abspath(__file__)), "character", "sdwake.c")
SDK_RAM = 0x2406c020                 # sdwake.c SDK_RAM: sdk_t (6 words); the keep-alive reads into FatFs's window
SDK_RAM_BYTES = 24
SDK_IDLE_SITE = 0x0809ab30           # the file thread's idle point: bl 0x08044f90, r0 = the heartbeats
SDK_EXTERNS = {
    "sdk_x_stamp": 0x08044f90 | 1,   # the file thread's heartbeat stamp
    "sdk_x_read": 0x0804504c | 1,    # SD_read
    "sdk_x_write": 0x080450bc | 1,   # SD_write
    "sdk_x_cmd12": 0x0804c9e4 | 1,   # SDMMC_CmdStopTransfer
    "sdk_x_state": 0x0804d7e4 | 1,   # HAL_SD_GetCardState
}
SDK_DISKIO = ((0x080bf038, 0x0804504c, "sdk_rd"), (0x080bf03c, 0x080450bc, "sdk_wr"))
SDK_IMMEDIATES = (                   # (va, stock bytes, new bytes, what)
    (0x08045070, "41f28832", "42f22832", "SD_read's wait for the transfer, movw r2, #5000 -> #9000"),
    (0x080450e2, "41f28832", "42f22832", "SD_write's wait for the transfer, movw r2, #5000 -> #9000"),
)
SDK_GUARDS = (                       # (va, bytes, what)
    (0x0809ab2e, "b3e7", "the stream loop, back to its top"),
    (0x0809aa50, "01283846", "the file thread: no stream message (r0 != 1), r0 = the heartbeats"),
    (0x0804441c, "01236375", "the card check: 1 at +0x15 when the card is mounted"),
    (0x0804cefa, "90f83050edb2012d", "HAL_SD_ReadBlocks_DMA: the handle's State at +0x30, READY 1"),
    (0x0804cf10, "032380f83030", "... BUSY 3 while a transfer runs"),
    (0x08059298, "48380124", "xTickCount, 0x24013848"),
    (0x0804ca00, "c36843f08003", "SDMMC_CmdStopTransfer: CMDSTOP, then CMD12"),
    (0x08056164, "f0a40024", "FatFs[], 0x2400a4f0 (find_volume)"),
    (0x08054e92, "c578", "sync_window: wflag at +3"),
    (0x08054eda, "836b8b42", "move_window: winsect at +0x38"),
    (0x08054ef4, "04f13c01", "... the window at +0x3c"),
    (0x08054f00, "01204ff0ff35", "... and a failed read leaves winsect -1"),
)


def apply_sd_wake(d):
    """Guard sdwake.c's facts, append it, take the idle stamp and diskio's entries, set the waits."""
    for va, raw, what in SDK_GUARDS:
        _guard(d, va, raw, what)
    if bytes(d[SDK_IDLE_SITE - BASE:SDK_IDLE_SITE - BASE + 4]) != enc_b_bl(SDK_IDLE_SITE, 0x08044f90, True):
        refuse(f"The file thread's idle stamp at {SDK_IDLE_SITE:#x} is not stock's.")
    externs = dict(SDK_EXTERNS)
    for (slot, fn, _), ext in zip(SDK_DISKIO, ("sdk_x_read", "sdk_x_write")):
        cur = struct.unpack_from("<I", d, slot - BASE)[0]   # stock's, or the crash log's wrapper (--diag)
        if cur != fn | 1 and not (cur & 1 and BASE + STOCK_SIZE <= cur < BASE + len(d)):
            refuse(f"diskio's entry at {slot:#x} is neither stock's {fn:#x} nor the patch's.")
        externs[ext] = cur
    for va, old, _, what in SDK_IMMEDIATES:
        _guard(d, va, old, what)
    org = BASE + len(d)
    while org % 16:
        d += b"\0"
        org += 1
    code, syms = c_link(c_object("sdk", SDK_SRC), org, externs)
    org2 = _append(d, bytearray(code))
    assert org2 == org
    d[SDK_IDLE_SITE - BASE:SDK_IDLE_SITE - BASE + 4] = enc_b_bl(SDK_IDLE_SITE, org + syms["sdk_idle"], True)
    for slot, _, entry in SDK_DISKIO:
        struct.pack_into("<I", d, slot - BASE, (org + syms[entry]) | 1)
    for va, _, new, _ in SDK_IMMEDIATES:
        d[va - BASE:va - BASE + len(new) // 2] = bytes.fromhex(new)
    vprint(f"U' SD wake {len(code)} bytes at {org:#010x}: keep-alive after 10 s idle, 9 s transfer wait, "
           f"stop and retry, state {SDK_RAM:#x}")
    return org, syms


def apply_sd_recovery(d, wake=True):
    """Guard U's sites and facts, append U, take its calls, set its limit; then
    sdwake.c, unless the crash log goes first (--diag: it wraps stock's diskio
    entries, so a read the retry rescues still shows on its log)."""
    for va, raw, what in SD_GUARDS:
        _guard(d, va, raw, what)
    for site, target in SD_PROOFS:
        if bytes(d[site - BASE:site - BASE + 4]) != enc_b_bl(site, target, True):
            refuse(f"The call at {site:#x} is not stock's call of {target:#x}.")
    for site, target, _ in SD_CALLS:
        if bytes(d[site - BASE:site - BASE + 4]) != enc_b_bl(site, target, True):
            refuse(f"The SD call at {site:#x} is not stock's call of {target:#x}.")
    for va, old, _, what in SD_IMMEDIATES:
        _guard(d, va, old, what)
    code, syms = build_sd_hook(BASE + len(d))
    org = _append(d, bytearray(code))
    for site, _, entry in SD_CALLS:
        d[site - BASE:site - BASE + 4] = enc_b_bl(site, org + syms[entry], True)
    for va, _, new, _ in SD_IMMEDIATES:
        d[va - BASE:va - BASE + len(new) // 2] = bytes.fromhex(new)
    vprint(f"U SD recovery {len(code)} bytes at {org:#010x}: ACMD41 {SD_START_MS} ms on the clock, "
           f"CMD8 x{SD_CMD8_TRIES}, DAT0 {SD_FREE_MS} ms, errors post {SD_ERR_MSG}, record {SD_RAM:#x}")
    if wake:
        apply_sd_wake(d)
    return org, syms


# --- X: the crash log (--diag; a diagnostic build on 2.3.11-mod, never a release) --------------
# GitHub issue #6: 2.3.10-mod restarting during Brightness, Theme and preset
# saves, then looping at boot. Static reading found no cause, so this build
# records the next one. The module restarts only by WWDG1: every fault
# handler is `b .`, and the audio block refreshes the watchdog only while the
# file thread's and the UI's heartbeats are under 0xea5 blocks old. X takes
# the four fault vectors and the watchdog's early warning (IRQ 0), keeps what
# they find in the backup SRAM (stock never touches it, and it outlives every
# reset while powered), and at the next boot, for 30 s, shows the gist at the
# top of the screen. It never touches the card: dg2-dg3 also wrote
# crashNN.txt there, and that build looped after a restart (diag.c: dx_job).
# All of it is C (character/diag.c), its entries included; no patch RAM.
# The chip report (--v239 --boot-dump; character/bootdump.c): 2.3.9-mod plus
# REPORT.TXT to the card, once: the chip, its option registers, the
# bootloader and bank 2 summarised on the module (no 1010music code leaves
# it), and the card; for the "Unable to verify" past 768 KB issue
# (2026-11-16). bd1 (6d6b06bd) copied the bootloader out raw, for the owner's
# own module only; bd3 adds a CRC per 4 KB block of the bootloader. On
# 2.3.9-mod so it stays under 0x08100000.
BD_VERSION = "2.3.9-dg1"            # the owner's name; built as bd1-bd3
BD_SRC = os.path.join(os.path.dirname(os.path.abspath(__file__)), "character", "bootdump.c")
BD_SITE = 0x0808edea                 # the tml read's f_open(fil, path, FA_READ): settings.tml, file thread
BD_EXTERNS = {
    "bd_x_fopen": 0x08056edc | 1,    # FatFs f_open
    "bd_x_fwrite": 0x0805732c | 1,   # f_write (the settings save's, 0x0808ed48)
    "bd_x_fclose": 0x080576a6 | 1,   # f_close
}
BD_GUARDS = (
    (0x0808edda, "582200213046", "the tml read clears a 0x58-byte FIL before f_open"),
)


def apply_boot_dump(d):
    """Guard the tml read, append bootdump.c, take its f_open."""
    for va, raw, what in BD_GUARDS:
        _guard(d, va, raw, what)
    if bytes(d[BD_SITE - BASE:BD_SITE - BASE + 4]) != enc_b_bl(BD_SITE, 0x08056edc, True):
        refuse(f"The tml read's f_open at {BD_SITE:#x} is not stock's.")
    org = BASE + len(d)
    while org % 16:
        d += b"\0"
        org += 1
    code, syms = c_link(c_object("bd", BD_SRC), org, dict(BD_EXTERNS))
    org2 = _append(d, bytearray(code))
    assert org2 == org
    d[BD_SITE - BASE:BD_SITE - BASE + 4] = enc_b_bl(BD_SITE, org + syms["bd_fopen"], True)
    vprint(f"BD chip report {len(code)} bytes at {org:#010x}, at the tml read's f_open {BD_SITE:#x}")
    return org, syms


# --- ZP: 2.3.13-mod, for bootloaders that stop at 768 KB (2.3.12-zp1 in testing) ---
# Some modules' bootloaders write MICRO.BIN only up to 0x080fffe0, 768 KB from
# the app (GitHub, 2026-11: a 2020 module's); 2.3.12-mod is 823,680 bytes, and
# the rest fails their read-back as "Unable to verify". --zp keeps chr12, the
# Character object exactly as 2.3.12-mod has it, LZMA-compressed in flash and
# runs it from D2 SRAM: stock names D2 only in its MPU set-up, which marks it
# execute-never (no literal, movw/movt or allocator reaches it), and the
# 2.3.12-d2p probe saw no write to it through ten minutes of use, with the
# effects running from it at 0.6-0.7% more cycles and the same audio bit for
# bit. character/zpboot.c unpacks it at power-on, in place of main's call of
# the MPU set-up. Nothing writes flash.
